[187] = {"Maîtrise de la chasse au tigre", {"Ajeck Rouack de l'Expédition Nesingwary veut que vous chassiez 10 Anciens tigres de Strangleronce."}},
[188] = {"Maîtrise de la chasse au tigre", {"Ajeck Rouack de l'Expédition Nesingwary veut que vous tuiez Sin’Dall et que vous rapportiez sa Patte."}},
[189] = {"Oreilles de Bloodscalp", {"Obtenir 15 Oreilles de trolls Bloodscalp et les apporter à Kebok, à Baie-du-Butin."}},
[190] = {"Maîtrise de la chasse à la panthère", {"Le sire S. J. Erlgadin de l'Expédition Nesingwary veut que vous tuiez 10 Jeunes panthères."}},
[191] = {"Maîtrise de la chasse à la panthère", {"Le sire S. J. Erlgadin de l'Expédition Nesingwary veut que vous tuiez 10 Panthères."}},
[192] = {"Maîtrise de la chasse à la panthère", {"Le sire S. J. Erlgadin de l'Expédition Nesingwary veut que vous tuiez 10 panthères Ombregueule."}},
[193] = {"Maîtrise de la chasse à la panthère", {"Le sire S. J. Erlgadin de l'Expédition Nesingwary veut que vous lui rapportiez un Croc de Bhag'thera."}},
[194] = {"Contrôler la population des raptors", {"Hemet Nesingwary veut que vous tuiez 10 Raptors de Strangleronce."}},
[195] = {"Contrôler la population des raptors", {"Hemet Nesingwary veut que vous tuiez 10 Raptors flagellants."}},
[196] = {"Contrôler la population des raptors", {"Hemet Nesingwary veut que vous tuiez 10 Traqueurs de la jungle."}},
[197] = {"Contrôler la population des raptors", {"Hemet Nesingwary veut que vous tuiez Téthis, un raptor farouche et dangereux de Strangleronce."}},
[198] = {"Les marchandises du soldat Thorsen", {"Remettre les marchandises des gobelins au soldat Thorsen."}},
[199] = {"Une sombre menace se dessine", {"Retourner voir l'ingénieur en chef Hinderweir et lui montrer l'indice que vous avez découvert."}},
[200] = {"Herod la Paperasse", {"Trouver les registres de Herod la Paperasse."}},
[201] = {"L'enquête au camp", {"Trouver le camp des chasseurs et communiquer sa position à Krazek à Baie-du-Butin."}},
[202] = {"Le colonel Kurzen", {"Tuer 6 Troupes d'élite, 4 Lieutenants et rapporter la tête de Kurzen au lieutenant Doren au camp rebelle."}},
[203] = {"La seconde rébellion", {"Tuer 15 Guerriers de la jungle.","","Retourner voir le sergent Yohwa au camp rebelle."}},
[204] = {"Mauvaise médecine", {"Apporter 7 Remèdes tropicaux et 1 Extrait de fougère vénéneuse au sergentYohwa au Camp rebelle."}},
[205] = {"Sorcellerie troll", {"Apporter 4 Fétiches Skullsplitter à frère Nimetz au camp rebelle."}},
[206] = {"Mai'Zoth", {"Apporter la Vue de l'Esprit au frère Nimetz au camp rebelle."}},
[207] = {"Le mystère de Kurzen", {"Trouver les 4 tablettes et rapporter ces légendes au frère Nimetz."}},
[208] = {"La chasse au gros gibier", {"Hemet Nesingwary veut que vous lui rameniez la tête du roi Bangalash, le grand tigre blanc."}},
[209] = {"Les défenses Skullsplitter", {"Acquérir 18 Défenses de trolls Skullsplitter et les apporter à Kebok."}},
[210] = {"La cuisine de Krazeck", {"Apporter la Cocotte ébréchée de chez Krazeck à Krazeck le gobelin."}},
[212] = {"Un repas servi froid", {"Tuer un basilic Œil-de-glace, collecter un Cuissot de basilic glacé, et le rapporter à Angus Stern, au Solitaire bleu.","","<Pour réussir cette quête vous devez la terminer sans libérer votre esprit.>"}},
[213] = {"Une ponction musclée", {"Retrouver 8 Cristaux réduits et les apporter à Kebok à Baie-du-Butin."}},
[214] = {"Les masques rouges en soie", {"L'Eclaireur Riell de la tour de la Colline des sentinelles veut que vous lui rameniez 10 masques rouges en soie."}},
[215] = {"Les secrets de la jungle", {"Parler au lieutenant Doren au camp rebelle."}},
[216] = {"Entre un roc et un Crin-de-Chardon", {"Tuer 12 Vengeurs Crins-de-Chardon et 12 Chamans Crins-de-Chardon ; la plupart d’entre eux se trouvent à l’est de la grève de Zoram, dans le village des Crins-de-Chardon. Retourner voir Karang Amakkar, à l’avant-poste de Zoram'gar, à Ashenvale, une fois que vous aurez terminé."}},
[217] = {"À la défense des terres du roi", {"Tuer le chef des troggs, Grawmug, et ses deux gardes, Grinceur et Bagarreur, puis rendre compte de la situation au capitaine Rugelfuss à la Tour de garde méridionale."}},
[218] = {"Le journal volé", {"Grelin Whitebeard veut que vous tuiez Grik'nir le Froid et que vous lui rapportiez son journal."}},
[219] = {"Porté disparu", {"Protéger le caporal Keeshan sur le chemin des Carmines."}},
[220] = {"L'appel de l'eau", {"Apporter la Fiole d'eau la plus pure à Islen Waterseer dans les Tarides."}},
[221] = {"Worgens dans les bois", {"Tuer 12 worgens Messagers Plaie-de-nuit pour Calor en Darkshire."}},
[222] = {"Worgens dans les bois", {"Tuer 8 Crocs noirs Plaie-de-nuit et 8 Contaminés Plaie-de-nuit pour Calor en Darkshire."}},
[223] = {"Worgens dans les bois", {"Apporter la lettre de Calor à Jonathan Carevin."}},
[224] = {"À la défense des terres du roi", {"Le Montagnard Cobbleflint de la Tour de garde méridionale veut que vous tuiez 10 Troggs et 10 Eclaireurs Brisepierre."}},
[225] = {"La tombe effritée", {"Parler à Sirra Von'Indi à Darkshire."}},
[226] = {"Des loups aux trousses", {"Tuer 12 Loups redoutables affamés et 8 Loups redoutables enragés, puis retourner auprès de Lars au camp de Sven à la frontière ouest du bois de la Pénombre."}},
[227] = {"Morgan Ladimore", {"Parler au commandant Althea Ebonlocke à Darkshire."}},
[228] = {"Mor'Ladim", {"Tuer Mor'Ladim, puis rapporter son crâne au commandant Althea Ebonlocke à Darkshire."}},
[229] = {"La fille qui survécut", {"Parler au Gardien Sarah Ladimore à Darkshire."}},
[230] = {"Le camp de Sven", {"Apporter à Sven le Livre de la ferme de Sven."}},
[231] = {"L'amour d'une fille", {"Déposer la bague de Sarah Ladimore sur la tombe de Morgan Ladimore."}},
[232] = {"Course pour l'Apothicaire Zinge", {"Apporter le bon de commande à Alessandro Luca à Fossoyeuse."}},
[233] = {"La distribution du courrier de la Vallée des Frigères", {"Apporter la pile de lettres à Talin Keeneye."}},
[234] = {"La distribution du courrier de la Vallée des Frigères", {"Remettre la lettre à Grelin Whitebeard."}},
[235] = {"La Chasse d'Ashenvale", {"Parler à Senani Thunderheart, au Poste de Bois-brisé, à Ashenvale."}},
[237] = {"À la défense des terres du roi", {"Le Montagnard Gravelgaw de la Tour de garde méridionale veut que vous tuiez 10 Brise-crâne et 10 Prophètes Brisepierre, puis que vous retourniez le voir."}},
[238] = {"Course pour l'Apothicaire Zinge", {"Apportez une Trousse d'analyse de terrain à l'Apothicaire Zinge à Fossoyeuse."}},
[239] = {"Au secours de la garnison du ruisseau de l'ouest !", {"Se rendre à la garnison du ruisseau de l'ouest et parler à l’Adjoint Rainer."}},
[240] = {"Retour vers la Tremblotte", {"Retourner voir la Tremblotte avec des Gâteaux au crabe brun."}},
[243] = {"Sur le terrain", {"Parler à l'Ingénieur en chef Bilgewhizzle à Gadgetzan afin d'obtenir une source d'énergie pour la trousse d'analyse."}},
[244] = {"Des gnolls encombrants", {"Informer l’Adjoint Feldon."}},
[245] = {"Les plaies à huit pattes", {"Tuer 15 Araignées Tisse-venin pygmées, puis rendre compte à la Sentinelle Dodds au bois de la Pénombre."}},
[246] = {"L'appréciation du danger", {"Tuer 10 Bâtards des Carmines et 6 Braconniers des Carmines, et aller faire un rapport à l’Adjoint Feldon à Comté-du-Lac."}},
[247] = {"La chasse achevée", nil},
[248] = {"En regardant plus loin", {"Monter au sommet de la Tour de garde intacte près du Donjon de Guet-de-pierre, puis trouver dans quoi placer le Glyphe d'Azora."}},
[249] = {"Morganth", {"Tuer Morganth, puis rapporter son Pendentif des ombres à Théocritus, à la Tour d'Azora dans la forêt d'Elwynn."}},
[250] = {"Une sombre menace se dessine", {"Enquêter près de la rampe est du barrage et rapporter à l'ingénieur en chef Hinderweir un indice qui permettrait de deviner les intentions des nains Sombrefer."}},
[251] = {"La traduction de la lettre d'Abercrombie", {"Apporter la lettre à Ello, à Sirra Von'Indi."}},
[252] = {"La traduction pour Ello", {"Remettre la lettre traduite au seigneur Ello Ebonlocke."}},
[253] = {"La fiancée de l'Embaumeur", {"Trouver la tombe d'Eliza, retrouver le cœur de l'Embaumeur, puis retourner voir Ello Ebonlocke."}},
[254] = {"En creusant la terre", nil},
[255] = {"Mercenaires", {"Le magistrat Bluntnose de Thelsamar vous a embauché pour tuer 4 Ogres, 4 Brutes et 4 Massacreurs Mo'grosh."}},
[256] = {"ON RECHERCHE : Chok'sul", {"Tuer Chok'sul et rapporter sa tête au Magistrat Bluntnose de Thelsamar."}},
[257] = {"La fanfaronnade d'un chasseur", {"Tuer 6 Busards des montagnes et retourner auprès de Daryl le Jeune au pavillon des pérégrins en moins de 15 minutes."}},
[258] = {"Le défi d'un chasseur", {"Tuer 5 Anciens sangliers des montagnes et retourner auprès de Daryl le Jeune au pavillon des pérégrins en 12 minutes."}},
[261] = {"Sur le chemin écarlate", {"Détruire 30 Ravageurs morts-vivants, puis retourner voir Frère Anton, à la Combe de Nijel."}},
[262] = {"L'obscure silhouette", {"Montrer le livre que vous avez trouvé à la ferme de Sven aux habitants de Darkshire."}},
[263] = {"À la défense des terres du roi", {"Le Montagnard Wallbang de la Tour de garde méridionale veut que vous tuiez 10 Chamans et 10 Briseurs d'Os Brisepierre."}},
[264] = {"Jusqu'à ce que la mort nous sépare", {"Placer le pendentif de Clarice sur la tombe de Yuriv, dans la forêt des Pins argentés."}},
[265] = {"L'obscure recherche se poursuit", {"Voir si d'autres habitants ont des indices concernant l'obscure silhouette."}},
[266] = {"Une enquête à l'auberge", {"Chercher à l'auberge des indices concernant l'obscure silhouette."}},
[267] = {"La menace trogg", {"Apporter 8 Dents de pierre de troggs au capitaine Rugelfuss à la Tour de garde méridionale."}},
[268] = {"Retourner voir Sven", {"Retourner voir Sven avec le journal complété de la Tremblotte."}},
[269] = {"À la recherche de la sagesse", {"Donner le journal complété de la Tremblotte à l'évêque Farthing à Hurlevent."}},
[270] = {"La Flotte perdue", {"Aller au port de Menethil, dans les Paluns, et parler à Glorin Steelbrow."}},
[271] = {"La vengeance de Vyrin", {"Tuer le Vieux Noiraud puis montrer le résultat à Daryl le Blanc-bec au pavillon des pérégrins."}},
[272] = {"L'épreuve du lion de mer", {"Trouver le Demi-pendentif d'agilité aquatique et le Demi-pendentif d'endurance aquatique. Parler aux habitants de Reflet-de-Lune pour obtenir des indices quant à l’endroit où ces objets se trouvent.","","Reformer le Pendentif du lion de mer à partir des deux moitiés. Vous devez vous trouver à proximité du sanctuaire de Remulos pour faire ceci.","","Apporter le Pendentif reformé à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune."}},
[273] = {"Approvisionnement du site de fouilles", {"Aller voir Huldar."}},
[274] = {"Une sombre menace se dessine", {"Sur ordre d'Ashlan Stonesmirk, retourner voir l'Ingénieur en chef Hinderweir pour l'informer de la nouvelle découverte."}},
[275] = {"Fièvre sur le pays", {"Tuer 12 Rampants des tourbières, puis retourner voir Rethiel, le Gouverneur vert, dans les Paluns."}},
[276] = {"Piétinements de pattes", {"Tuer 15 Gnolls Poils-moussus et 10 Bâtards Poils-moussus puis retourner voir Rethiel, le Gouverneur vert, dans les Paluns."}},
[277] = {"Feu interdit", {"Rapporter à Rethiel, le Gouverneur vert, 9 Silex bruts."}},
[278] = {"Une sombre menace se dessine", {"Collecter du Venin de rôdeuse, un Cristal Mo'grosh et une Larme de crocilisque pour l'Ingénieur en chef Hinderweir."}},
[279] = {"Griffes des profondeurs", {"Tuer 12 murlocs Branchies-bleues.","","Tuer Enfourneur et prendre sa tête.","","L'apporter à Karl Boran au port de Menethil."}},
[280] = {"Une sombre menace se dessine", {"Sur ordre de l'Ingénieur en chef Hinderweir, nager jusqu'à la base du barrage pour localiser le tonnelet de poudre et y verser la mixture de désamorçage pour empêcher une explosion."}},
[281] = {"Récupération de marchandises", {"Rechercher les caisses et les barils dans les camps murlocs le long de la côte."}},
[282] = {"Les observations de Senir", {"Aller voir le Montagnard Thalos."}},
[283] = {"Une sombre menace se dessine", {"La Mixture de désamorçage semble avoir fonctionné. Retourner voir l'Ingénieur en chef Hinderweir pour lui annoncer la bonne nouvelle."}},
[284] = {"La recherche continue", {"Rechercher la Statuette de Menethil."}},
[285] = {"À la recherche d'autres taudis", {"Continuer à fouiller les taudis des murlocs pour retrouver la Statuette de Menethil."}},
[286] = {"Rapporter la statuette", {"Apporter la Statuette de Menethil à Karl Boran."}},
[287] = {"Le repaire des Frostmane", {"Explorer le repaire des Frostmane et tuer 5 Chasseurs de tête Frostmane pour Senir Whitebeard à Kharanos."}},
[288] = {"La IIIe flotte", {"Acheter une Cruche d'hydromel pour le Premier Officier Fitzsimmons."}},
[289] = {"L'équipage maudit", {"Tuez 13 marins maudits, 5 soldats de marine maudits et le second Snellig. Rapportez la tabatière de Snellig au second Fitzsimmons au port de Menethil."}},
[290] = {"Levée de la malédiction", {"Obtenir du capitaine Halyndor la Clé du coffre-fort de \"l'Intrépide\".","","Utiliser la clé pour ouvrir le Coffre verrouillé de l'Intrépide."}},
[291] = {"Les rapports", {"Livrer le rapport de Senir au Sénateur Barin Redstone à Forgefer."}},
[292] = {"L'Oeil de Paleth", {"Apporter l'Oeil maudit de Paleth à Glorin Steelbrow."}},
[293] = {"Purifier l'Oeil", {"Apportez l’œil maudit de Paleth à l’archevêque Benedictus, à la cathédrale de la Lumière, dans la ville de Hurlevent."}},
[294] = {"La vengeance d'Ormer", {"Sur ordre d'Ormer Ironbraid à l'Excavation de Whelgar, tuer 10 Hurleurs tachetés et 10 Raptors tachetés."}},
[295] = {"La vengeance d'Ormer", {"Tuez 10 faucheurs tachetés et 10 tranchegueules tachetés pour Ormer Tressefer, puis allez le voir au site de fouilles de Whelgar."}},
[296] = {"La vengeance d'Ormer", {"Sur ordre d'Ormer Ironbraid, de l'Excavation de Whelgar, tuer Grondecroc et revenir avec l'une de ses serres une fois la tâche accomplie."}},
[297] = {"Réunir les idoles", {"Apporter 8 Idoles de pierre sculptée à Magmar Fellhew."}},
[298] = {"Compte rendu d'avancement des fouilles", {"Apporter le Compte rendu d'avancement d'Ironband à Jern Hornhelm à Thelsamar."}},
[299] = {"Découverte du passé", {"À la demande du prospecteur Whelgar, parcourir l'Excavation à la recherche des 4 fragments de tablette : Ados, Modr, Golm et Neru."}},
[301] = {"Rapport à Forgefer", {"Porter le Compte rendu d'avancement d'Ironband au Prospecteur Foudrepique."}},
[302] = {"De l'explosif pour Ironband", {"Parler à Jern Hornhelm à Thelsamar."}},
[303] = {"La guerre contre les Sombrefer", {"Motley Garmason, à Dun Modr, vous demande de tuer 15 Nains sombrefer, 5 tunneliers sombrefer, 5 saboteurs sombrefer et 5 démolisseurs sombrefer."}},
[304] = {"Une tâche sinistre", {"Tuer Balgaras le Crasseux et rapporter son oreille à Longbraid le Macabre à Dun Modr."}},
[305] = {"À la recherche de l’équipe de fouilles", {"À la demande de Tarrel Rockweaver, aller jusqu'à l'Excavation et contacter Merrin Rockweaver."}},
[306] = {"À la recherche de l’équipe de fouilles", {"Retourner voir Tarrel Rockweaver avec la lettre de Merrin."}},
[307] = {"Bas les pattes !", {"Aller à la Mine du Ru d'argent pour prendre 4 lots d'Equipement de mineur.","","Retourner voir le Montagnard Foudrepique."}},
[308] = {"Distraire Jarven", nil},
[309] = {"Protection de la cargaison", {"S'assurer que Miran et la cargaison parviennent au Site de fouilles puis en informer le Prospecteur Ironband."}},
[310] = {"Bières rivales", {"Aller au sous-sol de la distillerie Thunderbrew à Kharanos et remplacer un Tonneau de Thunder Ale par un Tonneau de Barleybrew Scalder."}},
[311] = {"Retour chez Marleth", {"Apporter le Tonneau de Thunder Ale à Marleth Barleybrew au Village de Brassetout."}},
[312] = {"La réserve volée de Tundra MacGrann", {"Récupérer la caisse de viande séchée de Tundra MacGrann dans la Caverne du Vieux Barbeglace."}},
[313] = {"L'antre Gris", {"Réunir 8 Peaux de Wendigo et les apporter au Pilote Stonegear."}},
[314] = {"Protection du troupeau", {"Sur demande de Rudra Amberstill, tuer Vagash et rapporter un de ses crocs à la ferme des Amberstill."}},
[315] = {"La bière parfaite", {"Apporter 6 Brins de chatoyante à Rejold Barleybrew au village de Brassetout."}},
[317] = {"Ravitailler le Crache-vapeur", {"Réunir 4 morceaux de Viande de sanglier et 2 Fourrures d'ours épaisses et les livrer au pilote Bellowfiz au dépôt de Steelgrill."}},
[318] = {"L’Evershine", {"Demander un tonneau d'Evershine à Rejold Barleybrew au village de Brassetout."}},
[319] = {"Une faveur pour un tonneau d’Evershine", {"Tuer 6 Ours Griffeglace, 8 Anciens sangliers des rochers et 8 Léopards des neiges, puis retourner voir Rejold Barleybrew à Brassetout."}},
[320] = {"Retour vers Bellowfiz", {"Donner le Tonneau d'Evershine au Pilote Bellowfiz au Dépôt de Steelgrill."}},
[321] = {"Le fer de sancteforge", {"Fouiller l'épave de l'Albatros, dans les Paluns."}},
[322] = {"Béni soit ce bras", {"Apporter la Caisse de lingots de sancteforge à Grimand Elmore, à Hurlevent."}},
[323] = {"Prouver votre valeur", {"Tuer 15 Ecumeurs squelettes, 3 Soigneurs squelettes et 3 Gardiens squelettes puis retourner voir Sven."}},
[324] = {"Les lingots perdus", {"Collecter 5 Lingots de sancteforge puis retourner voir Glorin Steelbrow, dans les Paluns."}},
[325] = {"En armes et prêt", {"Apporter le Fléau de Morbent à Sven, dans le bois de la Pénombre."}},
[328] = {"La clé cachée", {"Utiliser la Petite Clé en cuivre pour ouvrir le Coffre-fort de Herod la Paperasse."}},
[329] = {"L'espion découvert !", {"Apporter la Note maculée de boue au lieutenant Doren, au camp rebelle."}},
[330] = {"Composition des patrouilles", {"Parler au caporal Sethman."}},
[331] = {"Rapport au Lieutenant Doren", {"Parler au Lieutenant Doren."}},
[332] = {"Publicité pour la cave à vins Gallina", {"Aller à la Cave à vins des Gallina et apporter à Suzetta Gallina le Bon pour une bouteille de vin gratuite."}},
[333] = {"Harlan a besoin d'être approvisionné", {"Aller à la Boutique de tailleur du canal et donner à Rema Schneider la Demande de tissu, pour Harlan Bagley."}},
[334] = {"Un paquet pour Thurman", {"Aller chez les Couturiers Larson, dans le quartier des mages de Hurlevent, pour donner à Thurman Schneider son Matériel de couture."}},
[335] = {"Un noble brassage", {"Sur ordre de Zardeth de la Griffe noire, rapporter une Larme de Tilloa de Darkshire et une Racine de Musquash des Paluns."}},
[336] = {"Un noble brassage", {"Apporter la Bière brune de la Griffe noire au seigneur Wishock dans la Chambre du requérant."}},
[337] = {"Un vieux livre d'histoire", {"Rendre le livre « l'Histoire de Hurlevent » à la Bibliothèque de Hurlevent."}},
[338] = {"« Les vertes collines de Strangleronce »", {"Rassembler les pages manquantes du manuscrit des « Vertes collines de Strangleronce ». Une fois les quatre chapitres complétés, les rendre à Barnil."}},
[339] = {"Chapitre I", {"Rapporter les pages 1, 4, 6 et 8 des Vertes collines de Strangleronce de Nesingwary à Barnil Stonepot pour achever le Chapitre I."}},
[340] = {"Chapitre II", {"Rapporter les pages 10, 11, 14 et 16 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Stonepot pour achever le Chapitre II."}},
[341] = {"Chapitre III", {"Rapporter les pages 18, 20, 21 et 24 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Stonepot pour achever le Chapitre III."}},
[342] = {"Chapitre IV", {"Rapporter les pages 25, 26 et 27 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Stonepot pour achever le Chapitre IV."}},
[343] = {"En parlant de fermeté", {"Allez à la Bibliothèque royale dans le Donjon de Hurlevent pour parler à Milton Sheaf. Il trouvera le livre sur la métallurgie dont Frère Kristoff a besoin pour son discours."}},
[344] = {"Frère Paxton", {"Parler au frère Paxton, à l’abbaye de Comté-du-Nord."}},
[345] = {"Provisions d'encre", {"Aller voir le contremaître Oslow de Comté-du-Lac et lui demander du minerai de rethban."}},
[346] = {"Retourner voir Frère Kristoff", {"Retourner voir Frère Kristoff sur la Place de la Cathédrale. Lui donner le livre « les Tensions du fer »."}},
[347] = {"Minerai de rethban", {"Réunir 5 charges de Minerai de rethban et les apporter à Frère Paxton à la bibliothèque de Comté-du-Nord."}},
[348] = {"La fièvre de Strangleronce", {"Chercher le Sorcier-docteur Unbagwa pour qu'il invoque Mokk le Sauvage. Apporter le Cœur de Mokk à Fizracket."}},
[349] = {"La fièvre de Strangleronce", nil},
[350] = {"Le point de vue d'un vieil ami", {"Parler à Elling Trias à Hurlevent."}},
[351] = {"Trouver OOX-17/TN !", {"Apporter la balise de détresse au robot guidé d'Oglethorpe."}},
[353] = {"Livraison pour Foudrepique", {"Livrer le Paquet au montagnard foudrepique au Loch Modan."}},
[354] = {"Morts dans la Famille", {"Rapporter les restes de Gregor, de Nissa et de Thurman à Coleman Farthing, à Brill."}},
[355] = {"Parler à Sevren", {"Parler au magistrat Sevren à Brill."}},
[356] = {"Patrouille d'arrière-garde", {"Tuer 8 Horreurs sanguinolentes et 8 Esprits vagabonds, puis revenez voir Linnea, à son camp."}},
[357] = {"Le Nom de la Liche", {"Rapporter le livre de sorts de la Liche et le donner à Bethor Iceshard à Fossoyeuse."}},
[358] = {"Les Profanateurs", {"Tuer des Profanateurs Poils-putrides et des Gnolls Poils-putrides.","","Rapporter les Ichors d'embaumement au magistrat Sevren à Brill."}},
[359] = {"Mission des Réprouvés", {"Parler à la Garde noire Linnea."}},
[360] = {"Retourner voir le Magistrat", {"Retourner voir le Magistrat Sevren à Brill."}},
[361] = {"Une lettre perdue", {"Trouver Yvette Farthing. Lui donner la lettre de Thurman Agamand."}},
[362] = {"Les Moulins Hantés", {"Tuer Devlin Agamand et ramener ses restes à Coleman Farthing à Brill."}},
