[2038] = {"Les fournitures perdues de Bingles", {"Trouver et rapporter à Bingles son matériel :","","La Clé de Bingles, le Tournevis de Bingles, le Marteau de Bingles et le Capsuleur soufflant de Bingles."}},
[2039] = {"Trouvez Bingles", {"Trouver Bingles Blastenheimer, au Loch Modan."}},
[2040] = {"Assaut souterrain", {"Récupérer l'Indicateur Gnoam dans les mortemines et le ramener à Shoni la Silencieuse à Hurlevent."}},
