[2239] = {"Rapport d'Onin", {"Porter le rapport d'Onin à Hulfdan à Forgefer."}},
[2240] = {"La Chambre secrète", {"Lire le journal de Baelog, explorer la Chambre secrète, puis rendre compte au Prospecteur Foudrepique."}},
[2241] = {"Pomme d'amour", {"Porter la fleur de Jannok à Syurna à Darnassus."}},
[2242] = {"L'appel du destin", {"Trouver Sethir l’Ancien et rapporter tout indice découvert à Syurna."}},
[2258] = {"Les réactifs des Terres ingrates", {"Apporter 5 Gésiers de busard, 10 Crocs de coyote des rochers et 5 Fragments d'élémentaire de roche à Jarkal Mossmeld, à Kargath, dans les Terres ingrates."}},
[2260] = {"L'ordre d'Erion", {"Voyager vers Hurlevent pour y rencontrer Renzik \"le Kriss\"."}},
[2278] = {"Les Disques de platine", {"Parler au Gardien des pierres pour connaître le Savoir qu'il défend. Une fois découvert ce qu'ils peuvent offrir, activer les Disques de Norgannon."}},
