[2478] = {"Mission : possible mais non probable", {"Voler la Clé de la tour de Silixiz au contremaître Silixiz, puis tuer deux Pantins mutants de la KapitalRisk, deux Patrouilleurs de la KapitalRisk, et deux Sentinelles de la KapitalRisk.","","Assassiner le grand contremaître Gallywix et prendre sa tête. Ouvrir le coffre de Gallywix et y voler la Mixture altérée de Zanzil. Apporter la Mixture et la tête de Gallywix à Shenthul à Orgrimmar, et attendre de nouvelles instructions."}},
[2479] = {"L'aide d'Hinott", {"Aller à Moulin-de-Tarren dans les contreforts d'Hillsbrad et livrer l'Échantillon de la mixture de Zanzil à Serge Hinott.","","Pour rejoindre Moulin-de-Tarren, prenez le zeppelin à Fossoyeuse et suivez la route du sud, à travers les Pins argentés et vers Hillsbrad. Suivez les panneaux !"}},
[2480] = {"L'aide d'Hinott", {"Attendre Serge Hinott pour achever le remède."}},
[2498] = {"Retour vers Denalan", {"Sur ordre de Rellian Greenspyre, aller voir Denalan au lac Al'Ameth."}},
