[3448] = {"La transmission du fardeau", {"Parler au mage Tymor à Forgefer."}},
[3449] = {"Les runes des arcanes", {"À l'aide de la Trousse de dessin, effectuer des reproductions de la Rune de Beth'Amara, de la Rune de Jin'yael, de la Rune de Markri, de la Rune de Sael'hai, puis se diriger vers la petite île près de la Péninsule méridionale d'Azshara et signaler au Pilote Xiggs Fuselighter de venir les prendre."}},
[3450] = {"Une collecte facile", {"Parler à Xiggs Fuselighter à Forgefer."}},
[3451] = {"Signal de la récupération", {"Parler à Xiggs Fuselighter à Forgefer et en obtenir un Lance-fusée standard."}},
[3452] = {"L'enveloppe de la flamme", {"Trouver et apporter un Symbole de Ragnaros à Velarok Lamevent."}},
[3453] = {"La Torche de vindicte", {"Attendre que Velarok Lamevent termine la Torche de vindicte."}},
[3454] = {"La Torche de vindicte", {"Prendre la Torche de vindicte."}},
[3461] = {"Le retour vers Tymor", {"Rapporter la Trousse de dessin du mage Tymor au mage Tymor, à Forgefer."}},
[3462] = {"L'écuyer Maltrake", {"Parler à l'écuyer Maltrake."}},
[3463] = {"Allumer le feu !", {"Mettre le feu aux Tours de garde nord, sud, est, et ouest en utilisant la Torche de vindicte à l'intérieur de chaque tour."}},
[3481] = {"Bibelots...", {"Ouvrir le coffre."}},
[3483] = {"Signal de la récupération", nil},
[3501] = {"Tout se compte en grandes quantités", {"Apporter des Fragments imparfaits de draenéthyste à Kum'isha et toucher une récompense pour chaque fragment rapporté."}},
[3503] = {"Réunion avec le Maître", nil},
[3513] = {"Le Parchemin runique", {"Apporter le Parchemin runique à la tour de garde Nord dans les Tarides."}},
[3514] = {"Présence de la Horde", {"Tuer le chef de l'Antre des Serres, Rynthariel le Maître des clés."}},
[3517] = {"L'art du vol", {"Trouvez la tablette de Beth’Amara, la tablette de Jin’yael, la tablette de Markri et la tablette de Sael’hai puis retournez voir Jediga à Valormok."}},
[3518] = {"Une livraison pour Magatha Totem-Sinistre", {"Apportez la tablette de Beth’Amara à Magatha Totem-Sinistre aux Pitons-du-Tonnerre."}},
[3519] = {"Un ami dans le besoin", {"Parler à Dirania Silvershine, à Sombrevallon."}},
[3520] = {"Esprits de Hurleurs", {"Capturer l’Esprit de 3 Hurleurs en Feralas, puis retourner voir Yeh'kinya à Port Gentepression."}},
[3521] = {"Antidote d'Iverron", {"Trouver 7 Champignons jacinthe, 4 Lys pétales de lune et 1 Ichor d'araignée Tissebois pour Dirania Silveshine dans Sombrevallon."}},
[3522] = {"Antidote d'Iverron", {"Apporter l’Antidote d'Iverron à Iverron avant que la limite de temps ne soit atteinte. Iverron se trouve près de la grotte, au nord."}},
[3523] = {"Le Fléau des Souilles", {"Pour aider Belnistrasz, lui parler de nouveau et lui rendre la Pierre de voeu qu’il vous avait donnée."}},
[3524] = {"Echouage", {"Récupérer des Os de créature marine sur la créature échouée, au sud d’Auberdine, puis les apporter à Gwennyth Bly'Leggonde, à Auberdine."}},
[3525] = {"L'extinction de l'idole", {"Escorter Belnistrasz jusqu'à l'Idole des hurans dans les Souilles de Tranchebauge.","","Protéger Belnistrasz tandis qu'il exécute le rituel pour arrêter l'idole."}},
[3526] = {"Ingénierie des gobelins", {"Pour en apprendre davantage sur l'Ingénierie gobeline, apporter le Manuel d'Ingénierie à Nixx Sprocketspring dans Gadgetzan."}},
[3527] = {"La prophétie de Mosh'aru", {"Apporter les Première et Deuxième tablettes Mosh'Aru à Yeh'kinya, à Tanaris."}},
[3528] = {"Le dieu Hakkar", {"Apporter l'Oeuf Rempli d'Hakkar à Yeh'kinya dans Tanaris."}},
[3541] = {"Livraison pour Jes'rimon", {"Apporter la Tablette de Jin'yael à Jes'rimon dans Orgrimmar."}},
[3542] = {"Livraison à Andron Gant", {"Apporter la Tablette de Markri à Andron Gant à Fossoyeuse."}},
[3561] = {"Livraison à l'archimage Xylem", {"Apporter la Tablette de Sael'hai à l'archimage Xylem dans Azshara."}},
[3562] = {"Le Paiement de Magatha à Jediga", {"Apporter la Note de Magatha à Jediga dans Azshara."}},
[3563] = {"Le Paiement de Jes'rimon à Jediga", {"Apporter la Note de Jes'rimon à Jediga dans Azshara."}},
[3565] = {"Le Paiement de Xylem à Jediga", {"Apporter la Note de Xylem à Jediga dans Azshara."}},
[3566] = {"Debout, Obsidion !", {"Assassiner Lathoric le Noir et Obsidion, puis retourner voir Thorius, à Forgefer, avec la Tête de Lathoric le Noir et le Coeur d'Obsidion."}},
[3567] = {"Au sommet", nil},
[3568] = {"Corruption Suintante", {"Avant de retourner voir le Chimiste Cuely, remplir les 4 Fioles vides aux étangs des marées, le long de la côte des Ruines d'Eldarath, à Azshara."}},
[3601] = {"Kim'jael évidemment !", {"Fouiller le Camp de base thalassien pour trouver la Boussole, la Lunette, le Poulet farci et le Wizzlegoober de Kim'Jael, puis les lui rapporter à Azshara."}},
[3631] = {"Invoquer un Palefroi corrompu", {"Parler à Strahad Farsan, dans les Tarides."}},
[3632] = {"Ingénierie des gnomes", {"Pour en apprendre davantage sur l'ingénierie gnome, apporter le Manuel d'Ingénierie au maître-artisan Overspark, à Forgefer."}},
[3635] = {"Ingénierie des gnomes", nil},
[3636] = {"Apportez la Lumière", {"Tuer Amnennar le Porte-froid, aux Souilles de Tranchebauge, pour l’Archevêque Benedictus."}},
[3638] = {"Le Vœu du secret", {"Pour devenir un Ingénieur gobelin, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore Nixx Sprocketspring dans Gadgetzan."}},
[3639] = {"Montrez votre travail", {"Apporter 20 Grandes Bombes en fer, 20 Dynamites Solides et 5 Moutons Explosifs à Nixx Sprocketspring dans Gadgetzan."}},
[3640] = {"Le Vœu du secret", {"Pour devenir un Ingénieur gnome, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore le maître-artisan Overspark, à Forgefer."}},
[3641] = {"Montrez votre travail", {"Apporter 6 Tubes de mithril, 1 Lunette de précision et 2 Leurres perfectionnés au Maître artisan Overspark à Forgefer."}},
[3644] = {"Le renouvellement de la Carte de membre", nil},
[3661] = {"Dans les faveurs d'Elune ?", {"Collecter 15 Plumes d'Indomptable dans les Hinterlands, pour Erelas Ambersky au village de Rut'theran."}},
[3681] = {"Le Tome de divinité", {"Parler à Duthorian Rall à Hurlevent."}},
[3701] = {"Les ruines fumantes de Thaurissan", {"Aller dans les ruines de Thaurissan, dans les Steppes ardentes. Récupérer des informations sur les Reliques de Thaurissan, puis retourner auprès de l’Historienne royale Archesonus."}},
[3702] = {"Les ruines fumantes de Thaurissan", {"Écouter l'historienne royale Archesonus raconter l'histoire de Thaurissan."}},
[3741] = {"Le collier d'Hilary", {"Trouver le Collier d'Hilary et le rapporter à Hilary à Comté-du-Lac."}},
[3761] = {"La terre d'Un'Goro", {"Apporter 20 Echantillons d'Humus d'Un'Goro à Ghede, à Thunder Bluff."}},
[3762] = {"L'aide à l'archidruide Runetotem", {"Parler à l'archidruide Hamuul Runetotem à Thunder Bluff."}},
[3764] = {"La terre d'Un'Goro", {"Apporter 20 Echantillons d'Humus d'Un'Goro à Jenal, à Darnassus."}},
[3765] = {"La dépravation au loin", {"Aller voir Gershala Nightwhisper à Auberdine."}},
[3781] = {"La recherche sur la Fibre d'aurore", {"Apporter le Bon pour des graines de l'archidruide à Mathrengyl Bearwalker dans l'enclave cénarienne à Darnassus."}},
[3784] = {"L'aide à l'archidruide Runetotem", {"Parler à l'archidruide Hamuul Runetotem à Thunder Bluff."}},
[3785] = {"Recherches sur la Fibre d'aurore", {"Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendis et deux Echantillons d'Humus d'Un'Goro pour essayer de cultiver des Fibres d'aurore.","","Apporter 10 Fibres d'aurore à Mathrengyl Bearwalker à Darnassus."}},
[3789] = {"Assister l'archidruide Staghelm", {"Parler à l'archidruide Fandral Staghelm à Darnassus."}},
[3791] = {"Le Mystère des Fibres d'aurore", {"Apporter 10 Fibres d'aurore à Quintis Jonespyre au bastion de Feathermoon."}},
[3821] = {"Le Rocher des Cognepeurs", {"S'aventurer dans les Steppes ardentes et découvrir ce qu'il est advenu de Sha'ni Proudtusk."}},
[3822] = {"Krom'Grul", {"Récupérer l’Anneau de nez de Sha'ni sur Krom'Grul, et le rapporter à Thal'trak, à Kargath. Fouiller les différentes grottes et mines du Rocher des Cognepeurs."}},
[3823] = {"Exterminer les Brûlentrailles", {"Tuer 15 Ogres-mages Brûlentrailles, 7 Ogres Brûlentrailles et 7 Brutes Brûlentrailles, puis retourner voir Oralius."}},
[3844] = {"C'est un Secret pour tout le monde", {"Rechercher dans l'étang un indice sur l'identité du propriétaire du radeau brisé."}},
[3845] = {"C'est un secret pour tout le monde", {"Examiner les objets du paquet et les apporter à leur propriétaire."}},
[3861] = {"COT-COT-CODEC !", {"Trouver de la Nourriture spéciale pour poulet et l'apporter à la poule que vous voulez aider. Lorsque vous l'aurez trouvée, encouragez-la (/acclame) avant d'essayer de lui donner la Nourriture spéciale pour poulet."}},
[3881] = {"Le sauvetage de l'expédition", {"Apporter une Caisse de nourriture et de l'Equipement de recherche à Williden Marshal dans le Cratère d'Un'Goro."}},
[3882] = {"Faites rouler les os", {"Apporter 8 Os de dinosaure à Spark Nilminer, au cratère d'Un'Goro."}},
[3883] = {"Ecologie étrangère", {"Utiliser la Fiole de raclement pour récolter un Echantillon de paroi de la ruche dans une des nurseries de la ruche Gorishi, à l’intérieur du cratère d'Un'Goro. Chercher les chambres qui contiennent des larves suspendues.","","Apporter l’Echantillon de paroi de la ruche à Hol'anyee Marshal dans le cratère d'Un'Goro."}},
[3884] = {"Le journal de Williden", {"Rapporter le Journal à Williden Marshal quelque part dans le Cratère d'Un'Goro."}},
[3901] = {"Faites cliqueter les thorax !", {"Tuez 12 Squelettes Cliquethorax, puis retournez voir le prêtre des ombres Sarvis au Glas."}},
[3902] = {"La chasse aux trésors", {"Fouiller Le Glas et ses alentours pour trouver 6 pièces de fournitures de récupération, et les ramener au Garde noir Saltain."}},
[3903] = {"Milly Osworth", {"Parler à Milly Osworth."}},
[3904] = {"Les vendanges de Milly", {"Apporter 8 seaux de la récolte de Milly à Milly Osworth à l’abbaye de Comté-du-Nord."}},
[3905] = {"Manifeste des vendanges", {"Apporter le Manifeste des vendanges à Frère Neals dans l’abbaye de Comté-du-Nord."}},
[3908] = {"C'est un Secret pour tout le monde", {"Apporter l’Epée de Linken à Donova Snowden dans le Berceau-de-l'Hiver."}},
[3921] = {"Wenikee Boltbucket", {"Apporter le Samophlange cassé à Wenikee Boltbucket."}},
[3922] = {"Les Petites pièces", {"Apporter 15 Rondelles de métal à Wenikee Boltbucket dans les Tarides."}},
[3923] = {"Rilli Greasygob", {"Apporter le Samophlange cassé à Rilli Greasygob à Orgrimmar."}},
[3924] = {"Manuel du Samophlange", {"Apporter le Manuel du Samophlange à Rilli Greasygob à Orgrimmar."}},
[4021] = {"La contre-attaque !", {"Apporter un Morceau de la bannière de Krom'zar à Regthar Deathgate, à l'ouest de la Croisée."}},
[4101] = {"Purifie Gangrebois", {"Apporter 15 Ambres de sang à Arathandris Silversky à Gangrebois."}},
[4102] = {"Purifie Gangrebois", {"Apporter 15 Ambres de sang à Maybess Riverbreeze à Gangrebois."}},
[4120] = {"La force de la corruption", {"Talo Thornhoof, à Camp Mojache, dans Feralas, voudrait que vous tuiez 12 Grizzlis de la griffe colérique et 12 Ravageurs Gangrepatte, à Gangrebois."}},
[4123] = {"Le Coeur de la montagne", {"Apporter le Cœur de la montagne à Maxwort Uberglint dans les Steppes ardentes."}},
[4124] = {"Le messager disparu", {"Parler à Ginro Hearthkindle dans le bastion de Feathermoon."}},
[4125] = {"Le messager disparu", {"Localiser le bateau du messager quelque part le long de la côte de Feralas."}},
[4126] = {"Hurley Blackbreath", {"Apporter la Recette perdue de la Thunderbrew à Ragnar Thunderbrew à Kharanos."}},
[4127] = {"Débris de bateau", {"Retourner au bastion de Feathermoon et montrer à Ginro Hearthkindle le Couteau perdu que vous avez découvert."}},
[4128] = {"Ragnar Thunderbrew", {"Parler à Ragnar Thunderbrew."}},
[4129] = {"Le couteau révélé", {"Apporter le Couteau perdu à Quintis Jonespyre au bastion de Feathermoon."}},
[4130] = {"La lecture psychométrique", {"Parler à Ginro Hearthkindle dans le bastion de Feathermoon."}},
[4131] = {"Les gnolls Griffebois", {"Fouiller les Camps des gnolls Griffebois dans la partie sud de Feralas pour trouver des indices sur les possessions du messager ou sur le messager lui-même."}},
[4133] = {"Vivian Lagrave", {"Parler à la maîtresse des ombres Vivian Lagrave à Kargath."}},
[4135] = {"Le Gouffre grouillant", {"À présent que la dernière destination connue de Raschal est découverte, continuez à le rechercher, lui ou ses restes, dans le Gouffre grouillant. D'après le message, il se trouve au sud des camps des gnolls Griffebois."}},
[4136] = {"Ribbly Screwspigot", {"Apporter la Tête de Ribbly à Yuka Screwspigot dans les Steppes ardentes."}},
[4141] = {"Muigin et Larion", {"Récolter 15 Pétales-de-sang et retourner voir Muigin."}},
[4142] = {"Visite à Gregan", {"Apporter une Pétale-de-sang à Gregan Brewspewer en Feralas."}},
[4143] = {"Brouillard maléfique", {"Récupérer 5 Echantillons de brume atal'ai puis retourner voir Muigin dans le cratère d'Un'Goro."}},
[4144] = {"Les pousses de Pétales-de-sang", nil},
[4145] = {"Larion et Muigin", {"Chasser 5 Flagellants Pétale-de-sang, 5 Batteurs Pétale-de-sang, 5 Ecorcheurs Pétale-de-sang et 5 Trappeurs Pétale-de-sang pour Larion au refuge des Marshal."}},
[4146] = {"Carburant de baguette", {"Remettre la Baguette déchargée et 5 Echantillons de brume atal'ai à Larion au refuge des Marshal."}},
[4147] = {"Atelier de Marvon", {"Se rendre à l'Atelier de Marvon Rivetseeker à Ratchet."}},
[4161] = {"Une recette kaldorei", {"Collecter 7 Petites pattes d'araignée pour Zarrin, à Dolanaar."}},
[4182] = {"La menace des draconiens", {"Tuer 15 Rejetons noirs, 10 Draconides noirs, 4 Wyrmides noirs et 1 Drake noir. Retrouver Helendis Riverhorn une fois la tâche accomplie."}},
[4183] = {"Les véritables maîtres", {"Voyager jusqu’à Comté-du-Lac et remettre la Lettre d'Helendis Riverhorn au Magistrat Solomon."}},
[4184] = {"Les véritables maîtres", {"Voyager vers Hurlevent et remettre la Demande d'aide de Solomon au généralissime Bolvar Fordragon.","","Bolvar demeure dans le Donjon de Hurlevent."}},
[4185] = {"Les véritables maîtres", {"Parler au généralissime Bolvar Fordragon après avoir parlé à dame Katrana Prestor."}},
[4186] = {"Les véritables maîtres", {"Apporter le Décret de Bolvar au Magistrat Solomon à Comté-du-Lac."}},
[4223] = {"Les véritables maîtres", {"Parler au maréchal Maxwell dans les Steppes ardentes."}},
[4224] = {"Les véritables maîtres", {"Parlez à John le Loqueteux pour apprendre ce qu'il est advenu du maréchal Windsor puis retournez voir le maréchal Maxwell lorsque vous aurez accompli cette tâche.","","Vous vous rappelez que le maréchal Maxwell vous a dit de le chercher dans une grotte au nord."}},
[4241] = {"Maréchal Windsor", {"Partir pour le mont Rochenoire au nord-ouest et pénétrer dans les Profondeurs de Rochenoire. Découvrir ce qu'il est advenu du Maréchal Windsor.","","Vous vous souvenez que John le Loqueteux a dit que Windsor avait été traîné en prison."}},
[4243] = {"À la poursuite d'A-mi 01", {"Trouver A-mi 01 dans le Cratère d'Un'Goro."}},
[4244] = {"À la poursuite d'A-mi 01", {"Trouver une Caisse en mithril et retourner près de A-mi 01 dans le Cratère d'Un'Goro."}},
[4262] = {"Grand seigneur Pyron", {"Tuer le Grand seigneur Pyron et retourner voir Jalinda Sprig.","","Jalinda vous a dit qu'il gardait la carrière. Peut-être devriez-vous chercher à cet endroit ?"}},
[4265] = {"L'évasion de la ruche", {"Libérer Raschal de la ruche de Zukk'ash.","","Revenir voir Ginro Hearthkindle au bastion de Feathermoon et lui dire que Raschal est sain et sauf."}},
[4266] = {"Accueil d'un héros", {"Parler à Shandris Feathermoon dans le bastion de Feathermoon."}},
[4267] = {"L'ascension des silithides", {"Apporter le Rapport de Raschal à Gracina Spiritmight à Darnassus."}},
[4281] = {"La livraison à Thalanaar", {"Apporter le Vieux colis à Falfindel Waywarder, à Thalanaar."}},
[4283] = {"CINQUANTE ! OUI !", {"Oralius veut 50 Médaillons de Rochenoire. Il y a de fortes chances de trouver ces médaillons sur les orcs des Steppes ardentes."}},
[4284] = {"Cristaux de puissance", {"Récupérer 7 Cristaux de puissance de chaque couleur (rouge, bleu, jaune et vert). Les apporter à J.D. Collie au refuge des Marshal."}},
[4285] = {"Le Pylône nord", {"Découvrir l'emplacement du Pylône de cristal nord dans le Cratère d'Un'Goro."}},
[4286] = {"Du beau matériel", {"Se rendre dans les Profondeurs de Rochenoire et trouver 20 Sacoches Sombrefer. Retourner voir Oralius lorsque vous aurez accompli cette tâche. Logiquement, ces sacoches devraient être sur les nains Sombrefer des Profondeurs de Rochenoire."}},
[4287] = {"Le Pylône est", {"Trouver l'emplacement du Pylône de cristal est dans le Cratère d'Un'Goro."}},
[4288] = {"Le Pylône ouest", {"Découvrir l'emplacement du Pylône de cristal ouest."}},
[4289] = {"Les gorilles d'Un'Goro", {"Apporter 2 Peaux de gorille d'Un'Goro, 2 Peaux de marteleur d'Un'Goro et 2 Peaux de foudroyeur d'Un'Goro à Torwa Pathfinder à l'entrée du cratère d'Un'Goro."}},
[4290] = {"La nourriture de Lar'korwi", {"Trouver la dernière victime de Lar'korwi et voler un Morceau de carcasse d'un battrodon, puis retourner voir Torwa Pathfinder au Cratère d'Un'Goro."}},
[4291] = {"Un parfum pour Lar'korwi", {"Apporter 2 Glandes de phéromone de ravasaure à Torwa Pathfinder près de l'entrée du Cratère d'Un'Goro."}},
[4292] = {"Un appât pour Lar'korwi", {"En utilisant le contenu de la Sacoche de Torwa, appeler Lar'korwi et le vaincre. Puis apporter la Tête de Lar'korwi à Torwa Pathfinder près de l'entrée du Cratère d'Un'Goro."}},
[4293] = {"Un échantillon de Limon...", nil},
[4294] = {"... et un échantillon de Limon", {"Ramasser des Echantillons de Gelée d'Un'Goro sur les gelées du Cratère d'Un'Goro. Puis, en utilisant le Matériel d'expérience qui se trouve à côté du Chimiste Fuely à Fossoyeuse, déceler l'échantillon le plus pur. Apporter 5 Echantillons purs d'Un'Goro au Chimiste Fuely."}},
[4296] = {"Tablette des Sept", {"Apporter la Transcription de la tablette à Maxwort Uberglint dans les Steppes ardentes."}},
[4300] = {"Les armes aux lames d'os", {"Apporter 8 Griffes blanches de ravasaure à Jes'rimon à Orgrimmar."}},
[4301] = {"Le puissant U'cha", {"Apporter la Peau d'U'cha à Torwa Pathfinder à l'entrée du Cratère d'Un'Goro."}},
[4321] = {"Ceci explique cela", {"Parler à J.D. Collie dans un moment."}},
[4324] = {"Yuka Screwspigot", {"Parler à Yuka Screwspigot dans les Steppes ardentes."}},
[4341] = {"Kharan Mighthammer", {"Aller dans les Profondeurs de Rochenoire et trouver Kharan Mighthammer.","","Le roi a mentionné que Kharan était retenu prisonnier là-bas ; cherchez une prison."}},
[4402] = {"Surprise aux pommes de cactus de Galgar", {"Apportez à Galgar 10 Pommes de cactus. Il vous a précisé qu'elles se trouvaient souvent à côté des cactus."}},
[4421] = {"La corruption des Jadefeu", {"Tuer 11 Liges de la corruption Jadefeu, 9 Traqueurs des ombres Jadefeu, 9 Voleurs Jadefeu et Xavathras. Retourner voir Eridan Bluewind, à Gangrebois, quand la mission est terminée."}},
[4449] = {"Piégé !", {"Tuer 8 Géologues Sombrefer et rapporter 15 morceaux d’Etoffe de soie à la personne enfermée de les toilettes de la gorge des Vents brûlants."}},
[4450] = {"Grand livre de Tanaris", {"Prendre la copie du Livre de Goodsteel, puis collecter les objets qui y sont listés avant d’aller voir Krinkle Goodsteel, à Tanaris."}},
[4451] = {"La Clé de la liberté", {"Aller dans la gorge des Vents brûlants et trouver une utilisation à la Clé des toilettes de Crasseboue que vous avez trouvée."}},
[4485] = {"Le Tome de noblesse", {"Parler à Duthorian Rall, à Hurlevent."}},
[4487] = {"Invoquer un Palefroi corrompu", {"Parler à Strahad Farsan, à Ratchet."}},
[4488] = {"Invoquer un Palefroi corrompu", {"Parler à Strahad Farsan, à Ratchet."}},
[4489] = {"Invoquer un Palefroi corrompu", {"Parler à Strahad Farsan, à Ratchet."}},
[4490] = {"Invoquer un Palefroi corrompu", {"Parler à Strahad Farsan, à Ratchet pour apprendre à invoquer un Palefroi corrompu."}},
[4492] = {"Perdu !", {"Trouver Ringo sur la crête de la Fournaise."}},
[4493] = {"La marche des silithides", {"Parler à l’alchimiste Pestlezugg à Gadgetzan."}},
[4494] = {"La marche des silithides", {"Parler à l’alchimiste Pestlezugg à Gadgetzan."}},
[4495] = {"Un bon ami", {"Trouver Iverron près de la grotte au nord."}},
[4496] = {"Fiasco dans la jungle", {"Apporter une Glande olfactive Gorishi et 5 Echantillons d'Humus d'Un'Goro à l’alchimiste Pestlezugg, à Gadgetzan."}},
[4501] = {"Attention aux pterreurdactyles", {"Tuer 10 Pterreurdactyles et 15 Pterreurdactyles frénétiques, puis parler à Spraggle Frock, au refuge des Marshal."}},
[4502] = {"Activité volcanique", {"Collecter 9 Echantillons de cendre Un'Goro sur les Elémentaires de brûlure qui se trouvent autour du volcan, dans le Cratère d'Un'Goro, puis les apporter à Liv Rizzlefix, à Ratchet."}},
[4503] = {"La machine volante de Shizzle", {"Apporter 8 Ecailles étoilées de dimeurtrodon et 8 Ecailles étoilées de pterreurdactyles à Shizzle, au refuge des Marshal."}},
[4504] = {"Ultra collant", {"Collecter 12 échantillons de Goudron ultra collant pour Tran'rek, à Gadgetzan."}},
[4505] = {"Puits de la corruption", nil},
[4512] = {"Un grand périple pour une petite gelée", {"Apporter 6 Pots de Limons maudits remplis et 6 Pots de Limons corrompus remplis à Laris Geardawdle, à Forgefer ."}},
[4542] = {"Un message pour le poste de Librevent", {"Apporter le Message urgent au garde-falaise Longhorn au Poste de Librevent."}},
