[4740] = {"On recherche : Fondeboue !", {"Trouver et tuer le murloc connu sous le nom de Fondeboue. On pense que la créature défend les huttes des murlocs au sud d'Auberdine près de l'eau.","","Annoncer la mort de Fondeboue à la Sentinelle Glynda Nal'Shea à Auberdine."}},
