[4762] = {"La Bondissante", {"Aller au nord d’Auberdine, à la première chute d’eau, le long de la Bondissante et prélever un échantillon de l’eau de l’étang.","","Retourner voir Thundris Windweaver, à Auberdine, avec le Prélèvement de la Bondissante."}},
[4763] = {"La corruption des Noirbois", {"Remplir le Bol de purification vide au Puits de lune d’Auberdine.","","Collecter un échantillon de fruit, de noix et de céréales dans les camps nord des furbolgs Noirbois.","","Mélanger les échantillons de nourriture à l’eau du bol et le placer à proximité du feu le plus proche de la rivière Bondissante, au camp nord. Cela fera venir le satyre corrupteur.","","Prendre son Talisman de corruption et l'apporter à Thundris Windweaver, à Auberdine."}},
[4767] = {"Le cavalier céleste", {"Apporter 10 Oeufs de wyverne de Haut-perchoir à Elu au poste de Librevent."}},
[4770] = {"Vers le pays natal", {"Escorter Pao'ka Swiftmountain à partir de Haut-perchoir, puis parler à Motega Firemane au poste de Blanc-relais."}},
[4781] = {"Les composants de la robe sanglante dorée enchantée", {"Apporter une Barre d'or à Xizk Goodstitch dans la vallée de Strangleronce."}},
[4782] = {"Les composants de la robe sanglante dorée enchantée", {"Retourner voir Menara Voidrender dans les Tarides."}},
