[4811] = {"Le cristal rouge", {"Voyager en direction de l’est en partant d'Auberdine et chercher un gros cristal rouge le long de la chaîne de montagne est de Sombrivage. Aller faire un rapport de ce que vous avez trouvé à la Sentinelle Glynda Nal'Shea à Auberdine."}},
[4812] = {"Comme l'eau tombe en cascade", {"Remplir le Tube d'eau vide au Puits de lune d’Auberdine, puis chercher le cristal rouge le long des falaises des montagnes à l’est de Sombrivage."}},
