[4821] = {"L'oeuf étrange", {"Rapporter l'Oeuf étrange à Hagar Lightninghoof au Poste de Librevent."}},
[4841] = {"Pacifier les centaures", {"Tuer 12 Eclaireurs galak, 10 Querelleurs galak, et 6 Chasse-vent galak, puis retourner auprès du garde-falaise Longhorn au Poste de Librevent."}},
[4865] = {"Serpent sauvage", {"Faire un rapport de vos trouvailles à Motega Firemane."}},
[4881] = {"Complot d'assassinat", {"Prévenir Kanati Greycloud au Poste de Blanc-relais qu'un complot le menace."}},
[4904] = {"Libre, enfin !", {"Escorter Lakota Windsong hors de la Cime de Noir-nuage, puis parler à Thalia Amberhide au Poste de Librevent."}},
