[7815] = {"Les Gueules d'acier, l'ami !", {"Katoom le pêcheur, du village des Revantusk des Hinterlands, veut que vous tuiez 15 tortues Gueules d’acier des mers. Retournez le voir lorsque vous aurez terminé."}},
[7816] = {"Gammerita, l'ami !", {"Katoom le pêcheur, du village des Revantusk dans les Hinterlands, veut que vous tuiez Gammerita et que vous récupériez le Meilleur appât de Katoom sur son cadavre.","","Katoom a mentionné que Gammerita rôdait sur la côte, avec d’autres tortues."}},
[7820] = {"Un don de laine", nil},
[7821] = {"Un don de soie", nil},
[7826] = {"Un don de laine", nil},
[7827] = {"Un don de soie", nil},
[7828] = {"Traquer les traqueurs", {"Le veneur Markhor du village des Revantusk, dans les Hinterlands, veut que vous tuiez 15 Traqueurs Crins-d'argent et 15 Hurleurs Crins-d'argent. Retournez le voir lorsque vous aurez terminé.","","D’après Makhor, les loups se cachent dans les régions sauvages des Hinterlands."}},
[7829] = {"Chasser les sauvages", {"Le veneur Markhor du village des Revantusk des Hinterlands veut que vous tuiez 20 Chouettards sauvages. Retournez le voir lorsque vous aurez terminé.","","Markhor a mentionné que les Chouettards sauvages vivaient dans les régions sauvages des Hinterlands."}},
[7830] = {"Venger les victimes", {"Le veneur Markhor, du village des Revantusk des Hinterlands, veut que vous tuiez un Seigneur du ciel Bec-rasoir et que vous récupériez une Plume de Seigneur du ciel. Revenez le voir lorsque vous aurez terminé votre tâche.","","D’après Makhor, les Seigneurs du ciel Bec-rasoir sont des créatures rares qui vivent dans les régions sauvages des Hinterlands."}},
[7833] = {"Un don de laine", nil},
[7834] = {"Un don de soie", nil},
[7839] = {"Les voyous Vilebranch", {"Le forgeron Slagtree du village des Revantusk, dans les Hinterlands, vous demande de retrouver les Outils perdus de Slagtree. Retournez le voir lorsque vous les aurez.","","Il a laissé entendre qu’ils pourraient se trouver dans l’un des temples des Vilebranch, au nord-est des Hinterlands. Vous devriez aussi jeter un coup d’œil au rocher de l’Affût."}},
[7840] = {"Lard a perdu son déjeuner !", {"Lard, du village des Revantusk, dans les Hinterlands, veut que vous retrouviez le Repas de Lard. Retournez le voir lorsque ce sera fait.","","D’après Lard, il l’aurait laissé dans l’île, au nord. Prenez garde aux trolls Vilebranch !"}},
[7841] = {"Un message pour les Wildhammer", {"Otho Moji'ko du village des Revantusk dans les Hinterlands veut que vous massacriez 15 Estafettes du Haut-val, 15 Eclaireurs du Haut-val, 15 Tireurs d'élite du Haut-val et 15 Forestiers du Haut-val. Revenez le voir lorsque vous aurez terminé.","","Vous pouvez trouver les elfes du Haut-val au Gîte de Quel’Danil, au nord-ouest des Hinterlands."}},
[7842] = {"Encore un message pour les Wildhammer", {"Otho Moji'ko, du village des Revantusk dans les Hinterlands, vous demande de lui ramener 10 Longues plumes élégantes prélevées sur les gryphons qui vivent dans les Hinterlands. Retournez le voir lorsque vous les aurez.","","On trouve des gryphons dans tous les Hinterlands."}},
[7843] = {"Le message final pour les Wildhammer", {"Otho Moji'ko, du village des Revantusk dans les Hinterlands, vous demande de vous rendre au Nid-de-l’Aigle, à l’ouest des Hinterlands. Vous devez placer le Message final pour les Wildhammer près du puits, au cœur de la ville. Retournez le voir lorsque vous aurez accompli votre tâche.","","Faites attention aux nains Wildhammer, qui risquent de mal le prendre, et aux autres membres de l’Alliance."}},
[7844] = {"Les cousins cannibales", {"Yayo’jin la Mystique, du village des Revantusk des Hinterlands, veut que tuiez 30 Scalpeurs Vilebranch et 15 Devins Vilebranch. Retournez la voir lorsque vous aurez terminé.","","D’après Yayo’jin, ces trolls se trouvent près des temples de Shaol'watha et d’Agol'watha, au nord-nord-est des Hinterlands."}},
[7845] = {"L’Ancien Torntusk a été enlevé !", {"L’Aînée Torntusk du village des Raventusk des Hinterlands vous demande de libérer son compagnon, l’Ancien Torntusk, de Jintha’alor.","","Vous savez qu’il est prisonnier au sommet de Jintha’alor, la capitale des Vilebranch, qui se trouve au sud des Hinterlands."}},
[7846] = {"Récupérez la clé !", {"L’Ancien Torntusk, à Jintha’alor, veut que vous tuiez Hitah’ya la Gardienne afin de récupérer la Clé des menottes qui le retiennent. Lorsque vous aurez cette clé, retournez voir l’Ancien Torntusk."}},
[7847] = {"Retourner voir l’Aînée Torntusk", {"L’Ancien Torntusk, à Jintha’alor, veut que vous retourniez voir l’Aînée Torntusk du village des Revantusk et que vous lui appreniez qu’il est sauvé."}},
[7849] = {"L’angoisse de la séparation", {"Le veneur Markhor du village des Revantusk, dans les Hinterlands, veut que vous récupériez les restes de son frère jumeau. Trouvez le Crâne du veneur Malkhor et les Os du veneur Malkhor, et ramenez-les au veneur Markhor.","","Markhor vous a dit que les restes de son frère avaient été abandonnés aux limons et aux loups des Vilebranch. Il a également mentionné l’existence d’une décharge remplie de limons à Jintha’alor, ainsi que celle d’un enclos à loups. Tous deux se trouvent près du sommet du temple."}},
[7850] = {"Les calices ténébreux", {"L’Aînée Torntusk du village des Revantusk, dans les Hinterlands, veut que vous récupériez 10 Calices de sang corrompu à Jintha’alor. Retournez voir l’Aînée Torntusk lorsque vous aurez terminé."}},
[7861] = {"ON RECHERCHE : la vile prêtresse Maléficia et ses sbires", {"Vous avez reçu l’ordre de tuer la vile prêtresse Maléficia et 20 Gardes Ama’zasi Vilebranch. Lorsque vous aurez terminé, allez voir l’Aînée Torntusk au village des Revantusk, dans les Hinterlands.","","La vile prêtresse Maléficia et la garde Aman’zasi ont leurs quartiers au sommet de Jintha’alor, dans les Hinterlands."}},
[7862] = {"Offre d’emploi : capitaine de la garde du village des Revantusk", {"Vous avez été chargé de liquider 20 Berserkers Vilebranch, 20 Chasseurs des ombres Vilebranch, 20 Sanguinaires Vilebranch et 20 Mangeurs d’âmes Vilebranch.","","Lorsque vous aurez terminé, allez parler à l’Aînée Torntusk, du village de Revantusk dans les Hinterlands."}},
