[8151] = {"Le charme du chasseur", {"Parlez à Ogtinc en Azshara."}},
[8153] = {"La ramure de coursier", {"Rapporter deux Ramures de coursier parfaites à Ogtinc en Azshara. Ogtinc vit au sommet des collines au nord-est des ruines d’Eldarath."}},
[8166] = {"La bataille pour le bassin d'Arathi !", {"Attaquez la mine, la scierie, la forge et la ferme, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière."}},
