[8231] = {"Vandales des flots", {"Apporter 6 Ecailles de vandale des flots à Ogtinc en Azshara.  Ogtinc demeure au sommet des falaises au nord-est des ruines d'Eldarath."}},
[8232] = {"Le drake vert", {"Apporter la Dent de Morphaz à Ogtinc en Azshara.  Ogtinc demeure au sommet des falaises au nord-est des ruines d'Eldarath."}},
[8273] = {"La gratitude d'Oran", nil},
[8365] = {"Ohé, des chapeaux de pirate !", {"La Modiste arrogante veut que vous lui rapportiez 20 Chapeaux de pirate des Mers du sud au port Gentepression, en Tanaris."}},
[8366] = {"Le racket des Mers du sud", {"Le chef de la sécurité Bilgewhizzle du port Gentepression, en Tanaris, veut que vous tuiez 10 Pirates des Mers du sud, 10 Flibustiers des Mers du sud, 10 Portefaix des Mers du sud et 10 Bretteurs des Mers du sud."}},
[8368] = {"La bataille du goulet des Chanteguerres", {"Apportez 3 Marques d’honneur chanteguerres à l’un des porteguerres de la Horde, devant les champs de bataille."}},
[8370] = {"La conquête du bassin d'Arathi", {"Apportez 3 marques d’honneur du bassin Arathi à un porteguerre de la Horde, devant les champs de bataille."}},
[8372] = {"La lutte pour le goulet des Chanteguerres", {"Apportez 3 Marques d'honneur du goulet des Chanteguerres à un général de brigade de l'Alliance, devant les champs de bataille."}},
[8374] = {"La revendication du bassin d'Arathi", {"Apportez 3 Marques d'honneur du bassin d'Arathi à un général de brigade de l'Alliance, devant les champs de bataille."}},
