[8410] = {"La maîtrise des éléments", {"Rassembler un échantillon d'air, de feu, de terre et d'eau pour Bath'rah la Vigie des Vents."}},
[8411] = {"Maîtriser les éléments", {"Apportez les éléments terre, air, feu et eau à Bath'rah la Vigie des vents."}},
[8412] = {"Le totem des esprits", {"Apportez les différents morceaux du Totem des esprits à Bath’rah la Vigie des Vents."}},
[8413] = {"Vaudou !", {"Apporter les Plumes vaudou à Bath'rah la Vigie des vents."}},
[8414] = {"La dissipation du mal", {"Récupérez 20 Pierres du Fléau des serviteurs et apportez-les au grand prêtre Thel'danis dans les Maleterres de l'ouest."}},
[8415] = {"La pointe du Noroît", {"Parler au commandant Ashlam Valorfist à la pointe du Noroît."}},
[8417] = {"Un esprit troublé", {"Parler au Héros déchu de la Horde à l'entrée des Terres foudroyées."}},
[8426] = {"La bataille du goulet des Chanteguerres", {"Apportez 3 Marques d’honneur du goulet des Chanteguerres à l’un des porteguerres de la Horde, devant les champs de bataille."}},
[8427] = {"La bataille du goulet des Chanteguerres", {"Apportez 3 Marques d’honneur du goulet des Chanteguerres à l’un des porteguerres de la Horde, devant les champs de bataille."}},
[8431] = {"La bataille du goulet des Chanteguerres", nil},
[8436] = {"La conquête du bassin d'Arathi", {"Apportez 3 marques d’honneur du bassin Arathi à un porteguerre de la Horde devant les champs de bataille."}},
[8460] = {"Allié des Grumegueules", {"Grifleur veut que vous prouviez votre valeur en tuant 6 Guerriers Mort-bois, 6 Guides Mort-bois et 6 Jardiniers Mort-bois.  Lorsque ce sera fait, retournez le voir dans le sud de Gangrebois, près du Sanctuaire d'émeraude."}},
[8461] = {"Les Mort-bois du nord", {"Nafien veut que vous tuiez 6 Protecteurs Mort-bois, 6 Vengeurs Mort-bois et 6 Chamans Mort-bois. Ensuite, retournez le voir dans le nord de Gangrebois, près de l'entrée du repaire des Grumegueules."}},
[8462] = {"Parler à Nafien", {"Suivre la route principale de Gangrebois vers le nord et parler à Nafien le furbolg. Il monte la garde à côté de l’entrée du repaire des Grumegueules."}},
[8551] = {"Le coffre du capitaine", {"Apporter le coffre au capitaine Hecklebury Smotts à Baie-du-Butin."}},
[8552] = {"L'écharpe à monogramme", {"Rendre l'Echarpe à monogramme à son propriétaire."}},
[8553] = {"Le sabre du capitaine Smott", {"Parler à Sprogger."}},
[8554] = {"Face à Negolash", {"Apporter 10 Ailes de busard grillées et 5 bouteilles de Vin de Junglevine dans le Canot de sauvetage du capitaine Smott.","","Tuer Negolash, et apporter le Coutelas de Smotts au capitaine Smotts, à Strangleronce."}},
[8893] = {"Le Super-Oeuf-O-Matic", nil},
[9052] = {"Le poison de Pétale-de-sang", {"Récupérez 8 Chapeaux de sang et 8 Dards de Gorishi, puis retournez voir Torwa Pathfinder au cratère d'Un'goro."}},
[9063] = {"Torwa Pathfinder", {"Parler à Torwa Pathfinder au cratère d'Un'goro."}},
[65593] = {"Les cœurs des amoureux", {"Apportez les Cœurs d’Avelina Lilly et d’Isaac Pearson à Carendin Halgar dans le Temple des Damnés."}},
[65597] = {"Le lien", {"Utilisez les Cœurs des amoureux pour invoquer et soumettre un incube, puis rapportez les Cœurs des amoureux à Carendin Halgar, dans le Quartier de la magie de Fossoyeuse."}},
[65601] = {"Les affres de l’amour", {"Parlez à Magar, à Orgrimmar."}},
[65602] = {"Qu’est-ce que l’amour ?", {"Récupérez la Figurine en bois et rapportez-la à Gakin le Tisse-noir, au Quartier des mages de Hurlevent."}},
[65603] = {"Le lien", {"Utilisez la Figurine en bois pour invoquer et asservir un incube, puis rapportez l’objet à Gakin le Tisse-noir à l’Agneau assassiné."}},
[65604] = {"Le lien", {"Utilisez l’Écharpe flétrie pour invoquer et asservir un Incube, puis rapportez-la à Gan’rul Bloodeye, à Orgrimmar."}},
[65610] = {"Comme tu me manques", {"Explorez le Lac Tombeciel en Ashenvale et rendez compte de vos découvertes à Gan’rul Bloodeye, à Orgrimmar."}},
[76156] = {"La traque de la Terre-Mère", {"Faufilez-vous dans la mine de la KapitalRisk au sud-est de Thunder Bluff et récupérez 5 charges excavatrices d’hydroglycérine dans les chariots de fournitures, puis retournez voir Boarton Ombre-Totem à Thunder Bluff."}},
[76160] = {"La traque de la Terre-Mère", {"Ramassez 8 pommes de Furie des vents au nord de Thunder Bluff, utilisez-les avec le mortier et le pilon, puis rapportez le résultat à Boarton Ombre-Totem."}},
[76240] = {"La traque de la Terre-Mère", {"Acheter ou attrapez un goujon brillant cru, puis utilisez l’ensemble de couteaux pour lever ses filets devant Boarton Ombre-Totem à Thunder Bluff."}},
[78088] = {"Un artéfact étrange", {"Apportez l’orbe d’Althalaxx à Delgren le Purificateur au poste de Maestra en Orneval."}},
[78089] = {"Les conseils de Hurlevent", {"Apportez l’orbe d’Althalaxx à Katherine la Pure, à Hurlevent."}},
[78090] = {"Seconde opinion", {"Trouvez le sanctuaire des démonistes dans Hurlevent et demandez un avis sur l’orbe."}},
[78091] = {"Avec une pincée de sels", {"Récupérez 14 sels d’invocateur sur les invocateurs rochenoires des Carmines, puis retournez voir Ursula Deline à Hurlevent."}},
