[92474] = {"Tomber avec panache", {"Sautez du haut de la tour de guet du bosquet de Thendal et utilisez votre compétence Marche sur l’air pour ralentir votre chute."}},
[92479] = {"Une lettre écrite à la hâte", {"Lisez la lettre écrite à la hâte et parlez à Tordrin Tigelame à l’abbaye de Comté-du-Nord."}},
[92481] = {"Élève des arcanes", {"Examinez le cristal de rappel luminescent, puis parlez à Dorii Murméclat dans le bosquet de Thendal."}},
[92482] = {"La voie de la chasse", {"Lisez la note gribouillée, puis parlez à Tai’ree Doublevue dans le bosquet de Thendal."}},
[92483] = {"Un foyer dans les ombres", {"Lisez la note simple, puis parlez à Akeri Lamebrune dans la tour de guet, dans le bosquet de Thendal."}},
[92484] = {"S’ouvrir aux éléments", {"Examinez le cristal de rappel bourdonnant, puis parlez au sculpte-vent Boro dans le bosquet de Thendal."}},
[92485] = {"Élève de la nature", {"Lisez le parchemin plié, puis parlez à Xyton Vent-argent dans le bosquet de Thendal."}},
[92489] = {"Puissance accablante", {"Tuez l’élémentaire de mana pour le grand sorcier Andromath à Hurlevent."}},
[92514] = {"Bienvenue à Shen’dar !", {"Parlez à Illaya Ambrevent et Coriella Calmebrise à Shen’dar."}},
[92515] = {"Le problème avec les fièregriffes", {"Collectez 10 fourrures de fièregriffe sur les fièregriffes des hautes-terres de Shen’dar."}},
[92516] = {"Harceleurs hippogriffes", {"Tuez 8 jeunes hippogriffes, 6 protecteurs hippogriffes et une matriarche hippogriffe dans les hautes-terres de Shen’dar."}},
[92517] = {"L’élément du crime", {"Tuez 10 bandits des hautes-terres et leur chef, Bennic « Mauvais vent », dans les hautes-terres de Shen’dar."}},
[92519] = {"Réapprovisionnement de l’infirmerie", {"Récupérez une caisse de toniques empaquetés au laboratoire de Jorell, à la ferme de Go’shek, puis retournez voir le docteur Gregory Victor au Trépas-d’Orgrim."}},
[92528] = {"Parmi les fidèles", {"Fouillez Falaath pour tenter de percer à jour les intentions de la secte dans les hautes-terres de Shen’dar."}},
[92529] = {"Falaath", {"Présentez-vous au missionnaire Jasaan près de l’entrée de Falaath.","","Si vous perdez votre marque d’Akir, retournez voir Sania Flot-d’Argent à Shen’dar pour la récupérer."}},
[92532] = {"La voie du guerrier", {"Lisez la note chiffonnée qu’on vous a donnée, puis cherchez la maître-lame Ren dans la tour de guet de Thendal."}},
[92544] = {"Voyous al’aketh", {"Tuez 6 brutes al’aketh, 4 néophytes al’aketh et Malduko Fracasse-nuage dans le bosquet de Thendal."}},
[92550] = {"Malheur dans les hautes-terres", {"Rendez-vous dans les ruines de Falaath et tuez 6 mande-foudre al’aketh et 4 foudres vivantes et rapportez la tête du commandant Cyclas."}},
[92551] = {"Fournitures volées", {"Récupérez 10 paquets de fournitures de Shen’dar volées à Falaath, dans les hautes-terres de Shen’dar."}},
[92553] = {"Remplir les garde-manger", {"Collectez 3 petits œufs et 8 morceaux de viande de trotteur sur les créatures des hautes-terres de Shen’dar."}},
[92579] = {"Vers Valanaar", {"Apportez le rapport écrit d’Aonda à Valennia Poing-Tempête, à Valanaar."}},
[92595] = {"Les Sculpte-vents", {"Écoutez ce qu’Illaya Ambrevent a à dire."}},
[92596] = {"L’Ordre suprême", {"Asseyez-vous et discutez avec Rathiril Lance-Solaire."}},
[92597] = {"Lecture des lignes telluriques", {"Utilisez votre compétence raciale Lecture de ligne tellurique à la ligne tellurique dans le bosquet de Thendal."}},
[92598] = {"Le don de vue céleste", {"Utilisez votre compétence raciale Vue céleste à la convergence élémentaire dans le bosquet de Thendal."}},
[92640] = {"Une situation désespérée", {"Parlez à Valennia Poing-Tempête à Valanaar et suivez ses instructions."}},
[92642] = {"Perturbation logistique", {"Éliminez 4 soigneurs al’aketh et 8 bagarreurs al’aketh dans les plaines Aérelles."}},
[92643] = {"Le transfuge", {"Trouvez le transfuge de la secte à la maison dans les hautes-terres, au nord-ouest de Valanaar."}},
[92644] = {"Des nouvelles regrettables", {"Apportez le cristal luminescent à Talaanis Chantelombre, à Valaanar."}},
[92645] = {"Briser la Briseuse", {"Tuez la commandante Belguilos dans les plaines Aérelles."}},
[92646] = {"La confrontation avec Lorthuna", {"Prenez le portail vers les hauteurs des flèches Rohashi et rejoignez Elaadrin Trombecalme et Ayessa Chantelaube dans leur confrontation avec la grande prêtresse Lorthuna."}},
[92679] = {"La dîme du sang", {"Écoutez ce qu’Alvarion Champ-des-Vents a à dire et trouvez Aamelia Champ-des-Vents au verger Champ-des-Vents."}},
[92682] = {"Rendez-vous utile", {"Collectez 10 pommes d’orage mûres et tuez 5 bandits affamés au verger Champ-des-Vents."}},
[92683] = {"Poussière de voltemouche", {"Récupérez 5 tas de poussière de voltemouche sur des voltemouches dans les plaines Aérelles."}},
[92684] = {"Trotteurs gloutons", {"Récupérez 7 filets de trotteur des trombes des plaines sur des trotteurs des trombes hargneux dans les plaines Aérelles."}},
[92685] = {"Les collines ont des yeux", {"Récupérez 7 masques de bandit tachés de sang sur des bandits de grand chemin dans les plaines Aérelles."}},
[92693] = {"Tenir bon sans mollir", {"Parlez à Aamelia Champ-des-Vents quand serez prête à affronter le chef des bandits."}},
[92698] = {"Quelle est ma tâche ?", {"Parlez de l’assemblage du cyclone défectueux à Aamelia Champ-des-Vents."}},
[92699] = {"Le magistère suprême", {"Allez voir Elaadrin Trombecalme à Valanaar."}},
[92700] = {"La grande oracle des cieux", {"Allez voir Ayessa Chantelaube à Valanaar."}},
[92701] = {"Vers Valanaar", {"Apportez le rapport écrit d’Aonda à Valennia Poing-Tempête, à Valanaar."}},
[92703] = {"Apporter la nouvelle", {"Parlez à Alvarion Champ-des-Vents à Valanaar."}},
[92706] = {"ON RECHERCHE : Bruuz", {"Apportez la nageoire dorsale de Bruuz à Gazleu, à Cabestan."}},
[92707] = {"Le Géant de la tanière", {"Apportez les garde-poignets de goliath à Drum Lagangrène à Trépas-d’Orgrim."}},
[92708] = {"Une grande aventure", {"Écoutez ce qu’Ayessa Chantelaube a à dire."}},
[92709] = {"Une grande aventure", {"Écoutez ce qu’Elaadrin Trombecalme a à dire."}},
[92727] = {"L’érudit disparu", {"Découvrez ce qui est arrivé à Fillion Flammebrise."}},
[92741] = {"Visiteuses indésirables", {"Rendez-vous dans la forêt de Trombenoire et récupérez 8 serres de criailleuses pour Iaadaria Vent-Amer à Valanaar."}},
[92742] = {"Tester les puits", {"Utilisez le kit d’échantillonnage d’eau de puits pour collecter des échantillons dans les puits de la ferme des Jansen et de la ferme des Molsen."}},
[92743] = {"La couronne d’un conquérant", {"Maintenez votre réputation auprès des Magram et rapportez une couronne de conquérant trouvée dans les terres Ingrates à Warug au village des Magram."}},
[92744] = {"Des branchies de Murloc", {"Alba Lunepâle vous demande de récupérer 7 branchies de Murloc de Longrivage sur les côtes de la marche de l’Ouest."}},
[92745] = {"Quelles sales mines !", {"Tuez 4 terrassiers kobold à la mine Veine-de-Jango et 6 mineurs Rivepatte à la carrière de la côte de l’Or."}},
[92747] = {"Espionnage de Ruisselune", {"Récupérez 8 fournitures d’ingénierie suspectes à Ruisselune."}},
[92748] = {"Consultation explosive", {"Rendez-vous au quartier des Nains à Hurlevent et cherchez un ingénieur pour vous aider."}},
[92749] = {"Un plan explosif", {"Obtenez 10 bâtons de dynamite basique en les fabriquant, en les échangeant ou à l’hôtel des ventes, puis retournez voir Fée Dérailleur dans le quartier des Nains, à Hurlevent."}},
[92750] = {"Détonation à distance", {"Parlez à une personne du renseignement de Hurlevent pour obtenir un détonateur à distance."}},
[92751] = {"Détonation à distance", {"Apportez le kit de détonateur à distance à Fée Dérailleur, au quartier des Nains de Hurlevent."}},
[92752] = {"Consultation explosive", {"Retournez voir Alba Lunepâle à la marche de l’Ouest."}},
[92753] = {"Destruction dans les Mortemines", {"Trouvez la forge cachée dans les Mortemines et placez les explosifs de destruction ultime à proximité. Rejoignez ensuite Alba Lunepâle à la sortie des Mortemines."}},
[92754] = {"Un nouveau besoin de protection contre l’ombre", {"Maintenez votre réputation auprès des Magram et rapportez 3 potions de protection contre l’Ombre supérieures à Mirda, au village des Magram, en Désolace."}},
[92755] = {"Mysticisme mystérieux", {"Maintenez votre réputation auprès des Gelkis et rapportez 3 essences mystiques supérieures à Haléa au village des Gelkis, en Désolace."}},
[92811] = {"Guerre économique", nil},
[92812] = {"Guerre économique", nil},
[92814] = {"J’ai besoin d’un tailleur", {"Maintenez votre réputation auprès des Gelkis et rapportez un masque blanc de bandit à Molkar au village des Gelkis, en Désolace."}},
[92817] = {"Technique du cuir", {"Maintenez votre réputation auprès des Gelkis et rapportez un harnais barbare à Talra au village des Gelkis, en Désolace."}},
[92818] = {"De grosses, non, DE MASSIVES haches en fer", {"Maintenez votre réputation auprès des Magram et rapportez 2 haches massives en fer à Grolkar au village des Magram, en Désolace."}},
[92819] = {"Destruction dans les Mortemines", {"Utilisez le détonateur."}},
[92834] = {"Rendre au centuple", {"Récupérez 10 charmes de pierre de vent al’aketh sur des sectateurs al’aketh au nord de Valanaar, dans les plaines Aérelles ou au sanctuaire d’Akir."}},
[92840] = {"Au gré du vent", {"Emportez l’Index Esoteria aux pierres dressées surplombantes, dans les hautes-terres de Shen’dar, et utilisez-le sur les formations de pierre des vents de la zone pour collecter des données."}},
[92849] = {"L’érudit disparu", {"Continuez à chercher Fillion Flammebrise."}},
[92850] = {"L’érudit disparu", {"Tuez la matriarche criailleuse dans la tanière des Criailleuses, puis rapportez sa tête à Fillion Flammebrise à Valanaar."}},
[92858] = {"ON RECHERCHE : Ohk’zi", {"Apportez le bâton d’Ohk’zi à Latronicus Lancelune au bastion de Pennelune."}},
[92860] = {"Au service de Zéphras", {"Allez voir Valennia Poing-Tempête et faites-lui savoir que l’Ordre suprême soutiendra son camp dans sa lutte contre les Al’Aketh."}},
[92867] = {"Une position à tenir", {"Éliminez les Rochepoings, le Syndicat et les Fânécorces qui se sont introduits dans le donjon de Stromgarde, puis retournez auprès du paysagiste Lomar."}},
[92871] = {"Au service de Zéphras", {"Allez voir Valennia Poing-Tempête et faites-lui savoir que les Sculpte-vents soutiendront son camp dans sa lutte contre les Al’Aketh."}},
[92872] = {"Les pas du devoir", {"Jetez la bourse de poussière tombale dans la Grande mer, puis retournez auprès du conservateur Alaric dans la crypte du donjon de Stromgarde."}},
[92878] = {"Réduit au silence", {"Apportez une preuve de la mort de Namida Totem-sinistre à Blaise Montgomery, au camp Mojache."}},
[92880] = {"Retour à Valanaar", {"Apportez le rapport de Yorana à Valennia Poing-Tempête à Valanaar."}},
[92881] = {"La requête du grand ancien", {"Parlez à Talaanis Chantelombre à Valanaar."}},
[92909] = {"La moisson des moissonneurs", {"Ozwin Pignondefer, à la ferme des Saldean, veut que vous lui rapportiez 14 isoressorts de golem et 5 gyrostabiliseurs de moissonneur."}},
[92910] = {"La moisson des moissonneurs", {"Apportez l’assemblage autocognitif de précision à Ozwin Pignondefer, à la ferme des Saldean."}},
[92911] = {"La récolte des moissonneurs", {"Ozwin Pignondefer, à la ferme des Saldean, veut que vous lui rapportiez 8 isoressorts de golem, 4 modulateurs en cuivre et une lunette basique."}},
[92914] = {"D’étranges pylônes", {"Explorez Shen’dralas pour trouver d’autres pylônes semblables à celui que vous avez découvert."}},
[92947] = {"Passage à l’action", {"Tuez 7 gardiens al’aketh, 7 mande-esprit al’aketh et 7 maîtres-lame al’aketh, puis faites votre rapport à Hyusaa Vivebrise au sanctuaire d’Akir."}},
[93016] = {"Une courte leçon d’histoire", {"Parlez à Mordent Ombrégale, à Shen’dralas, pour obtenir des informations sur les cristaux que vous avez réparés."}},
[93034] = {"Vallée des Ossements", {"Améliorez votre réputation auprès des Gelkis et localisez Nerlokh près de la vallée des Ossements, loin à l’est du village des Gelkis."}},
[93035] = {"Les ravageurs sachant ravager", {"Maintenez votre réputation auprès des Gelkis et éliminez 6 ravageurs morts-vivants, puis retournez voir Nerlokh à l’entrée sud de la vallée des Ossements."}},
[93036] = {"L’infiltration de la secte", {"Allez voir Sania Flot-d’Argent à Shen’dar."}},
[93037] = {"Révéler les renégats", {"Maintenez votre réputation auprès du clan Gelkis et rapportez 1 atours nécromantiques à Nerlokh, à l’entrée de la vallée des Ossements."}},
[93041] = {"Affronter la vérité", {"Maintenez votre réputation auprès du clan Gelkis et rapportez le crâne maudit et les atours nécromantiques gelkis à Uthek la Sage au village des Gelkis."}},
[93044] = {"Un cri purificateur", {"Maintenez votre réputation auprès des Gelkis et rapportez les larmes de Theradras à Uthek la Sage au village des Gelkis."}},
[93045] = {"Tester votre théorie", {"Maintenez votre réputation auprès des Gelkis et dissipez la malédiction nécromantique présente sur le crâne maudit. Retournez ensuite faire votre rapport à Nerlokh, près de la vallée des Ossements."}},
[93058] = {"Sauver les siens", {"Maintenez votre réputation auprès du clan Gelkis et sauvez 5 captifs gelkis dans la vallée des Ossements. Retournez voir Nerlokh lorsque vous aurez terminé."}},
[93062] = {"Enfouissement d’ossements", {"Maintenez votre réputation auprès du clan Gelkis et dissipez la malédiction de 8 invocations échouées un peu partout dans la vallée des Ossements."}},
[93065] = {"Préparation à la bataille", {"Parlez à Valennia Poing-Tempête dans les plaines Aérelles."}},
[93089] = {"La suite des évènements", {"Parlez à Elaadrin Trombecalme lorsque vous serez prête à quitter l’île de Zéphras."}},
[93090] = {"La suite des évènements", {"Parlez à Ayessa Chantelaube lorsque vous serez prête à quitter l’île de Zéphras."}},
[93159] = {"L’étrange ermite", {"Allez parler à l’étrange ermite de la forêt de Trombenoire pour en savoir plus à son sujet."}},
[93160] = {"Les richesses de la forêt", {"Collectez 8 glands de Trombenoire dans la forêt de Trombenoire."}},
[93161] = {"La poignée antique", {"Trouvez quelqu’un qui serait intéressé par la garde antique que vous avez trouvée dans les ruines de Ban’aethal."}},
[93162] = {"La tête de l’Oblitérateur", nil},
[93165] = {"La miséricorde tombe dans l’oreille d’un sourd", {"Récupérez 5 oreilles de sectateurs al’aketh sur les sectateurs al’aketh dans la forêt de Trombenoire, au sanctuaire d’Akir ou dans les plaines Aérelles."}},
[93172] = {"Libérez les creux", {"Détruisez 10 creux du vent dans la forêt de Trombenoire."}},
[93176] = {"Mes petits amis", {"Utilisez les objets du kit d’entomologiste novice pour trouver et attraper une tarentule arborescente, un spécimen de charançon des foins et un pique-chair."}},
[93224] = {"Totems centaures sculptés", {"Récupérez 5 totems centaures sculptés en tuant des Centaures de n’importe quel clan un peu partout en Désolace, puis rapportez-les au capitaine Pentigast à la combe de Nijel."}},
[93225] = {"Totems centaures sculptés", {"Récupérez 5 totems centaures sculptés en tuant des Centaures de n’importe quel clan un peu partout en Désolace, puis rapportez-les à Gurda Crin-Sauvage au poste de Rôdeur-fantôme."}},
[93226] = {"Acheter leur amitié : les Magram", {"Apportez le sac totémique à l’intendant du village des Magram en Désolace, afin d’augmenter considérablement votre réputation auprès de ce clan. Vous devez avoir un niveau de réputation Neutre ou supérieur auprès des Centaures du clan Magram."}},
[93227] = {"Acheter leur amitié : les Gelkis", {"Apportez le sac totémique à l’intendant du village des Gelkis en Désolace, afin d’augmenter considérablement votre réputation auprès de ce clan. Vous devez avoir un niveau de réputation Neutre ou supérieur auprès des Centaures du clan Gelkis."}},
[93317] = {"La saison des crabes", {"Récupérez 6 morceaux de viande de clampant chantevent."}},
[93318] = {"AVIS DE RECHERCHE : Vulgara l’Insatiable", {"Tuez Vulgara l’Insatiable dans les hautes-terres de Shen’dar et rapportez sa tête à Danarii Soufflevoile."}},
[93319] = {"Les pierres de vent chapardées", {"Collectez 10 pierres de vent chapardées sur des bandits des hautes-terres, dans les hautes-terres de Shen’dar."}},
[93320] = {"Défense des tours", {"Allez voir Yorana Roseauvent à la tour de guet orientale dans les plaines Aérelles."}},
[93341] = {"Les jardins Lugubres", {"Inspectez les jardins Lugubres près de Shen’dralas, puis retournez voir Mithéra au temple des environs."}},
[93362] = {"Ce qu’ils ont fait à mes pivoines", {"Abattez des plantes dans les jardins Lugubres, puis retournez voir Mithéra, à Shen’dralas."}},
[93394] = {"Rencontre avec le magistère", {"Trouvez le magistère Kirandis à l’intérieur du temple de Shen’dralas."}},
[93404] = {"Pourriture et regret", {"Rendez-vous à Maraudon, récupérez une fiole d’eau de Chanteterre et apportez-la à Astrebois, aux jardins Lugubres, en Désolace."}},
[93429] = {"Le sang de mon sang", {"Tuez 10 Perdus dans le sanctuaire des Friches."}},
[93430] = {"Récupération de l’appât", {"Trouvez le pêcheur perdu qui a volé l’appât de Pelluk et récupérez ce dernier."}},
[93443] = {"Caisse perdue", {"Rapportez la caisse perdue à Friz Faiblétincelle au port de Poudremèche, sur les rives Claires."}},
[93450] = {"Problèmes fantasmatiques", {"Prenez l’épée inachevée de Vindael et trouvez le moyen de la convoyer dans le monde des esprits. Ensuite, rapportez-lui la lame fantasmatique, à Shen’dralas."}},
[93459] = {"Plus d’oreilles d’Al’Aketh", nil},
[93461] = {"Bienvenue à Shen’dar !", {"Parlez à Rathiril Lance-Solaire et Coriella Calmebrise à Shen’dar."}},
[93464] = {"Un mage de passage", {"En Désolace, trouvez le mage qui connaît le pouvoir de la draenéthyste."}},
[93465] = {"Notes sur la draenéthyste", {"Emparez-vous des notes de Gimashi sur la draenéthyste et rapportez-les à Azore Aldamort."}},
[93546] = {"Du minerai de fer spectral", {"Cherchez des gisements de fer spectral à Shen’dralas et collectez 10 morceaux de minerai de fer spectral. Retournez voir Vindael, à Shen’dralas, quand vous en aurez suffisamment."}},
[93552] = {"Collecte de pierres de vent", {"Récupérez 15 blocs de pierres de vent sur des pierres de vent brutes dans le bosquet de Thendal."}},
[93568] = {"Un collier partiellement digéré", {"Rapportez le collier partiellement digéré à quelqu’un qui le reconnaît. Vous trouverez sans doute son propriétaire à l’intérieur ou dans les environs de Shen’dralas, en Désolace."}},
[93574] = {"La carapace de Nécrobi", {"Trouvez quelqu’un intéressé par la carapace de Nécrobi."}},
[93585] = {"Ma Lumière à moi", {"Escortez le père Tuttle jusqu’au havre Boueux."}},
[93594] = {"Des nouvelles du jardin", {"Trouvez Astrebois dans les jardins Lugubres, à Shen’dralas, en Désolace."}},
[93601] = {"Passer le blâme", {"Cherchez un Huran important dans la retraite de Dos-hirsute."}},
[93604] = {"Le sang d’Agamaggan", {"Rendez-vous aux souilles de Tranchebauge, récupérez du sang virulent d’Agamaggan, puis apportez-le à Kog’thug le Brave à la retraite des Dos-hirsute, en Désolace. Kog’thug a jugé nécessaire de vous rappeler que le simple sang d’Agamaggan du kraal de Tranchebauge ne serait pas suffisant."}},
[93644] = {"Le journal en lambeaux", {"Le texte semble suggérer que l’auteur du journal se trouve quelque part à Shen’dralas."}},
[93663] = {"Livraison perdue", {"Trouvez le messager disparu et faites en sorte de livrer l’envoi de Dar au havre Boueux."}},
[93678] = {"Résumé des notes sur la draenéthyste", {"Apportez la transcription des notes d’Azore à Magtoor au havre Boueux dans le marais des Chagrins."}},
[93680] = {"Clé de la ville", {"Récupérez la clé des égouts de Dalaran pour le magus Wordeen Toisevide à Moulin-de-Tarren."}},
[93735] = {"L’assemblage brisé", {"Trouvez Riaani Ventenuit dans la partie ouest de Valanaar."}},
[93736] = {"Esprits indésirables", {"Récupérez 10 essences de creux du vent sur les creux du vent de la forêt de Trombenoire."}},
[93737] = {"L’assemblage brisé", {"Parlez à Riaani Ventenuit et écoutez ce qu’il a à dire."}},
[93738] = {"L’assemblage brisé", {"Faites votre rapport à Ayessa Chantelaube à Valanaar."}},
[93739] = {"À la découverte de la Horde", {"Allez trouver Nazgrel au fort Grommash afin de recevoir de nouvelles instructions. Suivez ses indications pour retrouver Vol’jin, Cairne Sabot-de-Sang et dame Sylvanas Coursevent, puis entretenez-vous avec chacun d’eux."}},
[93740] = {"Sang pour sang", {"Récupérez 10 charmes de pierre de vent sur les cadavres de sectateurs al’aketh dans les plaines Aérelles."}},
[93746] = {"Une réponse ferme", {"Confrontez Belathaan Voeu-Radieux sur la route qui mène au sanctuaire d’Akir."}},
[93786] = {"Message ensanglanté", {"Terrassez 12 journaliers de Ruissepré et retournez voir Krom’rosh pour l’informer de votre succès."}},
[93787] = {"Un festin à portée de main", {"Volez 6 sacoches de nourriture à la ferme de l’Alliance à Ruissepré et retournez voir Krom’rosh."}},
[93788] = {"Lames réclamées", {"Récupérez 10 haches d’abattage sur les bûcherons du camp de bûcherons de Turner pour Kreza Sombreronce, à Rog’mar."}},
[93791] = {"Parler à Belann", {"Parlez à Belann Vif-Bois à Valanaar."}},
[93797] = {"La brise dans les branches", {"Apportez un rameau imprégné de vent à Belann Vif-Bois, à Valanaar."}},
[93835] = {"La confrontation avec Lorthuna", {"Prenez le portail vers les hauteurs des flèches Rohashi et rejoignez Elaadrin Trombecalme et Ayessa Chantelaube dans leur confrontation avec la grande prêtresse Lorthuna."}},
[93836] = {"Le destin de Zéphras", {"Parlez à Talaanis Chantelombre à Valanaar."}},
[93926] = {"Le guet occidental", {"Trouvez le garde-paix Vaaniel à la tour de guet occidentale."}},
[93927] = {"Une dernière demande", {"Récupérez la note trouvée à proximité de la dépouille du garde-paix et lisez-la pour décider d’un plan d’action."}},
[93948] = {"Livraison de chevalière", {"Apportez la chevalière de la famille Chantelombre à Talaanis Chantelombre, à Valaanar."}},
[93949] = {"Les insectes ont des oreilles", {"Tuez des sauteciels à Valanaar jusqu’à avoir éliminé 8 sauteciels enchantés."}},
[93951] = {"Sa plus belle plume", {"Collectez 8 plumes de duvet d’hippogriffe dans les hautes-terres de Shen’dar."}},
[93958] = {"Le sanctum intérieur", {"Parlez à Valennia Poing-Tempête dans le sanctum intérieur du sanctuaire d’Akir."}},
[93963] = {"À la découverte de l’Alliance", {"Allez trouver Randal Emerson au donjon de Hurlevent afin de recevoir de nouvelles instructions. Suivez ses indications pour retrouver le roi Magni Barbe-de-Bronze, le Grand Bricoleur Mekkanivelle et Tyrande Murmevent, puis entretenez-vous avec chacun d’eux."}},
[93976] = {"La marchande gobeline", {"Livrez la lame à la connaissance de Kreza Sombreronce sur les quais à l’est de Rog’mar."}},
[94003] = {"Le Rempart de Briseciel", {"Reprenez le Rempart des Briseciel à Zaal Pare-tempête au sanctuaire d’Akir."}},
[94004] = {"Commission d’artisan : élixir de force d’ogre", {"Obtenez les objets demandés par le client et apportez-les à l’endroit indiqué sur votre carte. Ce document doit être en votre possession pour que la transaction soit validée."}},
[94006] = {"Le grand esprit ursera", {"Parlez avec Urs’endris près de la cascade au nord-est de Valanaar."}},
[94007] = {"Dompter la bête", {"Présentez-vous à Quel’ana Vent-Vif à Valanaar."}},
[94013] = {"Dompter la bête", {"Utilisez le bâtonnet de domptage pour dompter une alpha vuldrène des plaines Aérelles. Entraînez-vous à combattre à ses côtés, puis rapportez le bâtonnet de domptage à Quel’ana Vent-Vif à Valanaar."}},
[94050] = {"Entraîner la bête", {"Parlez à Quel’dora Vent-Vif à Valanaar."}},
