[94438] = {"Une leçon de divinité", {"Prenez le Symbole de vie et utilisez-le pour ressusciter le nécrogarde Falgan dans la vallée de Tissevenin.","","Si vous égarez votre Symbole de vie, retournez voir Danitha Morr pour en obtenir un autre."}},
[94440] = {"Une leçon de divinité", {"Dérobez les plans d’attaque de la Croisade écarlate aux croisés écarlates de la vallée de Tissevenin, puis retrouvez le nécrogarde Billmuth à la forteresse de Bandarion."}},
[94441] = {"Une leçon de divinité", {"Parlez à Danitha Morr au donjon de la forteresse de Bandarion."}},
