[96105] = {"Le roi des plaines Sauvages", {"Utilisez l’appel des hauts-trotteurs pour appeler le chef de la troupe de lions. Tuez la bête et récupérez sa peau pour Neza Flaire-Sang à Rog’mar."}},
[96107] = {"Des plumes pour l’empennage", {"Apportez 6 plumes de busard des plaines à Neza Flaire-Sang, à Rog’mar."}},
[96108] = {"Flèches empoisonnées", {"Apportez 4 échantillons de venin de vipère de la clairière à Neza Flaire-Sang, à Rog’mar."}},
[96109] = {"Le carquois d’une chasseuse", {"Rapportez 6 peaux de lion prisées à Neza Flaire-Sang, à Rog’mar."}},
[96125] = {"Besoin de repos", {"Trouvez Dunston Willis quelque part à Bolder’ok."}},
[96126] = {"Le captif d’un Ogre", {"Trouvez Gronok le Boucher, tuez-le, et rapportez la clé des chaînes à Dunston."}},
[96130] = {"Chakuyak", {"Abattez Chakuyak, puis rapportez sa fourrure."}},
[96135] = {"Entendez mon appel", {"Utilisez les totems tordus pour mettre un terme au rituel des Hurans."}},
[96137] = {"Dague d’Ira", {"Terrassez 10 jeunes ravageurs noirs et 7 ravageurs noirs, puis retournez voir Sirra Von’Indi à Sombre-Comté pour de plus amples informations."}},
[96138] = {"Arc de Merrick", {"Terrassez 8 guerriers Brisepoing et 4 sous-chefs Brisepoing, puis retournez voir Sirra Von’Indi à Sombre-Comté pour en savoir plus."}},
[96139] = {"La famille Valor", {"Fouillez la Colline-aux-Corbeaux à la recherche de tout élément intéressant, puis retournez voir Sirra Von’Indi à Sombre-Comté."}},
[96204] = {"La colère de la Sculpte-vent", {"Accompagnez Lumina Chantelevent et aidez-la à s’échapper du donjon de Fenris."}},
[96222] = {"Khan Hratha", {"Rapportez le fragment de clé des Maraudines à Umarak, en Désolace."}},
[96241] = {"Causons toxines", {"Utilisez l’extracteur de toxines pour récolter 5 échantillons de toxine de la cime du Chagrin sur des cadavres rongés, à la cime du Chagrin."}},
[96243] = {"L’appel de la terre", {"Trouvez Teo Martel-tempête en Dun Morogh."}},
[96259] = {"Défendre les morts", {"Tuez 10 jeunes araignées de la cime du Chagrin et 5 soldates de la cime du Chagrin."}},
[96260] = {"Plus fort que l’acier", {"Récupérez 3 fils de soie cristalline sur des tisseuses de la cime du Chagrin."}},
[96261] = {"La mère des couvées", {"Tuez la mère des couvées Valraxx, à la cime du Chagrin."}},
[96264] = {"Soutien élémentaire", {"Éliminez Charlga Trancheflanc au kraal de Tranchebauge et recueillez des renseignements sur les plans des Hurans."}},
[96294] = {"Une vérité bien plus sinistre", {"Apportez la lettre récupérée sur la mère des couvées Valraxx à Muln Rageterre, sur le plateau de Guette-ciel."}},
[96332] = {"La vengeance du noyé récalcitrant", {"Pénétrez dans la prison d’Alcaz, puis tuez 15 soldats strashaz ainsi que 8 enchanteresses strashaz. Rapportez également la tête de la maîtresse des marées Ca’zass à la sergente Ulka."}},
[96334] = {"Foulards rouge sang", {"Pénétrez dans la prison d’Alcaz et récupérez 8 foulards rouge sang sur les Humains qui s’y trouvent."}},
[96335] = {"L’homme aux chaînes de fer", {"Récupérez la clé de menottes d’Alcaz sur l’Interrogateur dans la prison d’Alcaz."}},
[96337] = {"Plus précieux que l’or", {"Utilisez la note que Mason Connery vous a remise pour trouver son trésor caché."}},
[96339] = {"Récompense d’héritage : réplique de carabine à air comprimé de Forgefer", nil},
[96369] = {"Mauvaises nouvelles pour Folkar", {"Retournez voir le commandant Folkar."}},
[96381] = {"Une tâche un peu salissante", {"Entrez dans la prison d’Alcaz et tuez 15 soldats strashaz, ainsi que 8 enchanteresses strashaz. Rapportez également la tête de la maîtresse des marées Ca’zass à Sully McCleary."}},
[96390] = {"Étouffer le mal dans l’œuf", {"Tuez 10 espions sombrefer à Dun Morogh."}},
[96391] = {"La carte souterraine", {"Remettez la carte sombrefer au terre-voyant Farsen, à Dun Morogh."}},
[96392] = {"Le guet de Farsen", {"Parlez au terre-voyant Farsen et demandez-lui de vous prêter sa double vue pour observer la menace des Sombrefer."}},
[96393] = {"Incursion dans le Vieux Forgefer", {"Pénétrez dans la salle des Thanes, sous le Vieux Forgefer, et emparez-vous de la tête de Durgen Mornemartel."}},
[96394] = {"Les morts sans repos", {"Tuez 15 apparitions enragées et 10 âmes tourmentées, puis accordez le repos à l’esprit de Courbenclume."}},
[96395] = {"Une rancune ancestrale", {"Apaisez l’esprit de Faldrim Courbenclume, puis retournez voir la domestique fantomatique dans la salle des Thanes."}},
[96403] = {"Précieux héritages", {"Récupérez 8 héritages nains dans la salle des Thanes."}},
[96408] = {"Une visite à Dun Morogh", {"Inspectez le campement qui domine la carrière de Gol’Bolar."}},
[96438] = {"La bataille du convent de Mannoroc", {"Examinez le site de la bataille du convent de Mannoroc en Désolace."}},
[96476] = {"À la recherche d’Aeonas", {"Cherchez des traces d’Aeonas au sanctuaire d’Émeraude dans Gangrebois."}},
[96603] = {"Magie instable", {"Apportez 10 granules de magie instable à l’archimage Célindra, à Dalaran."}},
[96604] = {"Les grands espaces sauvages", {"Asseyez-vous près du feu de camp basique de Brakk et attendez de recevoir l’amélioration Repos amplifié."}},
[96605] = {"Les grands espaces sauvages", {"Asseyez-vous près du feu de camp basique de Kaga et attendez de recevoir l’amélioration Repos amplifié."}},
[96606] = {"Les grands espaces sauvages", {"Asseyez-vous près du feu de camp basique de Lyreena et attendez de recevoir l’amélioration Repos amplifié."}},
[96607] = {"Les grands espaces sauvages", {"Asseyez-vous près du feu de camp basique d’Eleanor et attendez de recevoir l’amélioration Repos amplifié."}},
[96608] = {"Les grands espaces sauvages", {"Asseyez-vous près du feu de camp basique d’Eric et attendez de recevoir l’amélioration Repos amplifié."}},
[96609] = {"Le goût de la maison", {"Apportez 10 bouteilles de vin chatoyant de Lune-d’Argent à Arille Mirazur à Dalaran."}},
[96626] = {"Introduction au camping : la cuisine", {"Parlez à Tomas, à Comté-de-l’Or, pour apprendre à cuisiner."}},
[96627] = {"L’aventurier", {"Parlez à Sam Salsepareille près de Comté-de-l’Or."}},
[96628] = {"L’aventurier", {"Apportez le paquet de fournitures à Eric Brillemartel près de Kharanos."}},
[96629] = {"Introduction au camping : la cuisine", {"Parlez à Gremlock Pilsnor, à Kharanos, pour apprendre à cuisiner."}},
[96630] = {"L’aventurière", {"Apportez le journal à Lyreena Lamebrune, près de Dolanaar."}},
[96634] = {"Introduction au camping : la cuisine", {"Parlez à Zarrin, à Dolanaar, pour apprendre à cuisiner."}},
[96638] = {"L’aventurier", {"Parlez à Raan Aile-sauvage près de Shen’dar."}},
[96646] = {"Introduction au camping : la cuisine", {"Parlez à Zerril Douce-Brise à Shen’dar pour apprendre à cuisiner."}},
[96652] = {"L’aventurier", {"Apportez le journal à Brakk près de Tranchecolline."}},
[96655] = {"Introduction au camping : la cuisine", {"Parlez au cuisinier Torka, à Tranchecolline, pour apprendre à cuisiner."}},
[96656] = {"L’aventurière", {"Parlez à Eleanor Shackleton, près de Brill."}},
[96658] = {"Introduction au camping : la cuisine", {"Parlez à William Pickman, à Brill, pour apprendre à cuisiner."}},
[96659] = {"L’aventurière", {"Apportez le paquet de fournitures à Kaga Sabot-sauvage près de Sabot-de-Sang."}},
[96661] = {"Introduction au camping : la cuisine", {"Parlez à Pyall Sabots-Feutrés, à Sabot-de-Sang, pour apprendre à cuisiner."}},
[96770] = {"La tête du féticheur", {"Tuez le féticheur Zum’rah et rapportez sa tête à l’archimage Lan’dalock, à Dalaran."}},
[96771] = {"La vengeance des Bien-nés", {"Rendez-vous au bastion Krol’dok et terrassez Zalfan Lunombre."}},
[96772] = {"Le journal du dragon", {"Récupérez le journal de Zarla dans les profondeurs de la prison d’Alcaz."}},
[96773] = {"L’œil du Porte-froid", {"Récupérez l’Œil du Porte-froid dans les souilles de Tranchebauge."}},
[96774] = {"L’idole des anciens Gurubashi", {"Récupérez une idole antique des Gurubashi dans la cité Submergée."}},
[96775] = {"Tête de Zum’rah", {"Tuez le féticheur Zum’rah et rapportez sa tête à Mazu’kon, en Mulgore."}},
[96776] = {"La radiance d’An’she", {"Récupérez le cristal connu sous le nom de radiance d’An’she, dans Maraudon."}},
[96779] = {"Sabotage du Syndicat", {"Trouvez le seigneur Tomas dans le donjon de Fort-de-Durn, dans les contreforts de Hautebrande, et tuez-le. Revenez ensuite voir Myrokos Sourdeforme."}},
[96781] = {"Qu’est-ce qu’ils manigancent ?", {"Volez le rapport d’éclaireur de Barton, puis rapportez-le à Myrokos Sourdeforme, au manoir de Ravenholdt."}},
[96782] = {"Extraction clandestine", {"Retrouvez la lame de la maison Perenolde et l’égide royale de Perenolde dans les ruines d’Alterac. Rapportez-les ensuite à Myrokos Sourdeforme."}},
[96783] = {"Un moyen d’infiltration", {"Volez un uniforme du Syndicat au manoir de Nordclos afin d’infiltrer le donjon de Stromgarde."}},
[96784] = {"Maître du déguisement", {"Portez le déguisement d’un membre du Syndicat, puis trouvez quelqu’un qui soit au courant de la transaction secrète au donjon de Stromgarde."}},
[96785] = {"Motus", {"Dans le donjon de Stromgarde, trouvez de quoi convaincre Anastasia de vous révéler les détails de cette transaction secrète."}},
[96786] = {"La piqûre du Syndicat", {"Interrompez la transaction secrète et récupérez l’objet destiné au Syndicat. Rapportez-le ensuite à Myrokos Sourdeforme, au manoir de Ravenholdt."}},
[96797] = {"L’orphelin", {"Rendez-vous au Rempart-du-Néant dans les terres Foudroyées et retrouvez le sergent Danneth."}},
[96798] = {"Dans les ténèbres", {"Trouvez le sergent Danneth quelque part dans les grottes des Anneaux du serpent, au sud-est de Rempart-du-Néant."}},
[96800] = {"Retard de retour", {"Récupérez La Magie perdue des maîtres des runes au monastère Écarlate."}},
[96821] = {"Toutes pattes dehors", {"Tuez 6 rampantes noirecrêtes et 6 rôdeuses noirecrêtes dans le sud de Durotar, puis informez-en Gar’thok à Tranchecolline."}},
[96822] = {"Pour l’honneur", {"Récupérez la hache d’armes d’écumeur, l’arc d’écumeur et le bouclier d’écumeur aux alentours du donjon de Tiragarde, puis rapportez-les à Turroc à Tranchecolline."}},
[96825] = {"Ces fruits pourraient se défendre", {"Le cuisinier Torka de Tranchecolline souhaite que vous ramassiez 8 figues de Barbarie dans les terres des Tranchecrins à l’ouest de la ville."}},
[96873] = {"Une douleur dans la nuque", {"Pa’zula du village de Sen’jin vous demande de récupérer 3 résidus lumineux. Vous pourrez obtenir des résidus lumineux en désenchantant les pendentifs maléficiés obtenus sur les Trolls des îles de l’Écho."}},
[96874] = {"Spinal Hache", {"Ug’thok d’Orgrimmar souhaite que vous récupériez 5 échines défraîchies sur les bêtes des falaises du Tonnerre, en plus de 5 silex à aiguiser brutes."}},
[96875] = {"Les bêtes des falaises du Tonnerre", {"Kamari d’Orgrimmar souhaite que vous récupériez 5 peaux de lézard rugueuses sur les bêtes des falaises du Tonnerre, ainsi que 2 peaux légères traitées."}},
[96876] = {"Le sac perdu d’Ukor", {"Rapportez son sac à Ukor dans le sud de Durotar."}},
[96877] = {"Le sabot d’Halikor", {"Rapportez le sabot d’Halikor à Orgrimmar."}},
[96895] = {"L’émissaire de l’Aube d’argent", {"Trouvez le membre de l’Aube d’argent près de l’entrée de Fossoyeuse."}},
[96896] = {"Une juste cause", {"Assistez à la conversation entre Danitha Morr et Leonid Barthalomew le Révéré."}},
[96897] = {"Le Culte des damnés", {"Tuez 8 néophytes sombres et 8 massacreurs sombres dans les clairières de Tirisfal."}},
[96898] = {"Les vestiges de la guerre", {"Rassemblez 12 fragments de cristal nécrotique dans les clairières de Tirisfal."}},
[96899] = {"La forteresse de Bandarion", {"Retrouvez Leonid Barthalomew à la forteresse de Bandarion, dans les clairières de Tirisfal."}},
[96982] = {"Première virée à dos de kodo de monte", {"Examinez les kodos de monte pour choisir votre première monture."}},
[96984] = {"Cœur de la perturbation", {"Récupérez le granule arcanique pour le magus Wordeen Toisevide à Moulin-de-Tarren."}},
[96986] = {"Le Chevalier de la tombe", {"Triomphez d’Atrexis le Chevalier de la tombe dans la cité de Dalaran pour Melisara à Moulin-de-Tarren."}},
[96987] = {"Éducation opportuniste", {"Récupérez La fondation de Dalaran dans la cité de Dalaran pour Rexxie Pincentime près de l’entrée des égouts."}},
[96988] = {"Source de pouvoir", {"Récupérez 6 noyaux de sentinelles fissurés dans la cité de Dalaran pour le docteur Martin Felben à Fossoyeuse."}},
[96994] = {"Première virée à dos de loup de monte", {"Examinez les loups de monte pour choisir votre première monture."}},
[96996] = {"Première virée à dos de trotteur des trombes", {"Examinez les trotteurs de monte et choisissez votre première monture."}},
[96997] = {"Palefroi un jour, palefroi toujours", {"Examinez les chevaux morts-vivants pour choisir votre première monture."}},
[97003] = {"Chol’aruk le Vorace", {"Rapportez la tête de Chol’aruk à Gur’ak dans les Tarides."}},
[97005] = {"Chol’aruk le Vorace", {"Rapportez la tête de Chol’aruk à Bainham dans les Tarides."}},
[97017] = {"Première virée à dos de bélier", {"Examinez les béliers de monte pour choisir votre première monture."}},
[97018] = {"Apprentissage de la monte", {"Apprenez la compétence Apprenti cavalier auprès d’Ultham Corne-de-fer."}},
[97022] = {"Rendre compte à Danitha", {"Parlez à Danitha Morr à la forteresse de Bandarion."}},
[97029] = {"Eluvi’ana", nil},
[97046] = {"Première virée à dos de mécanotrotteur", {"Examinez les mécanotrotteurs de monte pour choisir votre première monture."}},
[97047] = {"Un cuistot en cage", {"Dans la base de Kurzen, trouvez la clé de la cage de Wendel ainsi qu’un déguisement pour lui permettre de s’évader."}},
[97048] = {"Retour à bon port", {"Allez voir la capitaine Aransas à Baie-du-Butin."}},
[97065] = {"Ça sent le poisson : scalaire de Keefer", nil},
[97074] = {"Apprentissage de la monte", {"Apprendre la compétence Apprenti cavalier auprès de Jartsam."}},
[97130] = {"Les secrets des anciens Gurubashi", {"Récupérez une idole antique des Gurubashi dans la cité Submergée."}},
[97173] = {"Magie noiregueule", {"Récupérez un totem rituel noiregueule au repaire des Noiregueules."}},
[97188] = {"Apprentissage de la monte", {"Apprendre la compétence Apprenti cavalier auprès de Binjy Siffleplume."}},
[97194] = {"Apprentissage de la monte", {"Apprendre la compétence Apprenti cavalier auprès de Kildar."}},
[97196] = {"L’Œil du Porte-froid", {"Récupérez l’œil du Porte-froid dans les souilles de Tranchebauge."}},
[97197] = {"Fragment des terres de Feu", {"Récupérez un fragment des terres de Feu dans les profondeurs de Rochenoire pour Alaana Marchetempête, en Mulgore."}},
[97198] = {"Magie noiregueule", {"Récupérez un totem rituel noiregueule au repaire des Noiregueules."}},
[97203] = {"Apprentissage de la monte", {"Apprendre la compétence Apprenti cavalier auprès de Velma Warnam."}},
[97204] = {"Apprentissage de la monte", {"Apprendre la compétence Apprenti cavalier auprès de Kar Chante-l’Orage."}},
[97205] = {"Apprentissage de la monte", {"Apprenez la compétence Apprenti cavalier auprès de Genn Beautemps."}},
[97220] = {"La faveur de Philmor", {"Apportez la cargaison de la Conciergerie à l’entrée de la réserve des Fromages de Trias, dans le quartier commerçant."}},
[97222] = {"Livraison au corps de garde", {"Montez la livraison destinée au corps de garde à l’étage de la boutique de Trias et déposez-la devant la porte."}},
[97223] = {"La matriarche griffesang", {"Apportez les œufs de la matriarche griffesang à Xar’Ti, au village de Sen’jin."}},
[97225] = {"Idoles de Loa oubliées", {"Récupérez 8 idoles de Loas oubliées sur les îles de l’Écho. Apportez-les au maître Gadrin, au village de Sen’jin."}},
[97234] = {"Salle de lecture", {"Apportez le matériel de lecture enveloppé à la bibliothèque de Hurlevent."}},
[97236] = {"Crochet de Githyiss", {"Apportez le crochet de Githyiss à quelqu’un d’Aldrassil qui s’intéresse tout particulièrement à l’étude des araignées."}},
[97237] = {"Récupérés à la main", {"Trouvez les matériaux de lecture situés dans la bibliothèque et apportez-les à Roy Lewells, au parc de Hurlevent."}},
[97242] = {"Le mélange de Yelmak", {"Prélevez des spécimens d’herbe polisson et de roseau qui poussent près des eaux de la vallée de l’Honneur et retournez voir Kor’geld à la boutique Alchimie et potions de Yelmak."}},
[97243] = {"L’appel du feu", {"Apportez la torche de la flamme dormante à Olariaan Vivebrûle au sanctuaire des Flammes, dans les plaines Aérelles."}},
[97244] = {"L’appel du feu", {"Tuez le prêtre céleste Faladiel dans les plaines Aérelles, puis récupérez son cœur."}},
[97245] = {"L’appel du feu", {"Trouvez le repaire de Kuramaa dans les hautes-terres de Shen’dar et vainquez l’esprit au combat. Une fois victorieuse, rapportez le masque de Kuramaa à Olariaan Vivebrûle dans les plaines Aérelles."}},
[97246] = {"En souffrance de pitance", {"Allez à la Fosse à feu de Borstan et dites à ce dernier que Thatog vous demande d’apporter son déjeuner à Migi."}},
[97249] = {"Son plat préféré", {"Apportez son repas à Migi derrière le fort Grommash."}},
[97250] = {"Accusé à tort, corrigé à raison", {"Tuez des soldats de l’Alliance qui empiètent sur les Tarides, à la frontière du marécage d’Âprefange. Puis retournez voir le grunt Logmar, au camp Taurajo."}},
[97253] = {"Foire à la ferraille", {"Récupérez 5 poignées de pièces complexes au camp des pirates, au sud de Cabestan, puis retournez voir Wrenix le Misérable, à Cabestan."}},
[97257] = {"L’appel du feu", {"Attendez qu’Olariaan commence le rituel au brasero d’offrande, puis suivez ses instructions.","","Vous devez remettre la flamme éternelle à Valanaar avant la fin du temps imparti."}},
[97263] = {"Votre paquet est arrivé", {"Apportez le paquet égaré à Eldrun."}},
[97265] = {"Furie contre les Fielfuries", {"Éliminez différents Satyres fielfuries à Sargeron, en Désolace, puis retournez auprès d’Aka’rai au village de Proie-de-l’Ombre."}},
[97275] = {"Droit au Whuut", {"Apportez la potion de Yelmak à Whuut."}},
[97277] = {"Grund et Gozwin", {"Trouvez le camp de Grund et Gozwin dans les collines du nord-ouest. Récupérez le journal de mécano de Gozwin et tuez le léopard des neiges rôdeur."}},
[97279] = {"Armes égarées", {"Récupérez 6 armes d’entraînement abandonnées, puis retournez auprès de Kzan Trancheronce, dans l’Antre."}},
[97281] = {"Une tempête en approche", {"Apportez l’orbe de tempête émoussé à Rezlak, près du ravin Asséché."}},
[97282] = {"Un potentiel houleux", {"Apportez 5 organes de lézard-tonnerre chargés à Rezlak, près du ravin Asséché."}},
[97284] = {"La vengeance de Vahlarriel", {"Éliminez des Orcs de la Lame ardente à la forteresse de Hache-Tonnerre, en Désolace, puis retournez auprès de Vahlarriel Tueur-de-démons à la combe de Nijel."}},
[97286] = {"Accès aux recherches", nil},
[97287] = {"Négociations avisées", {"Allez parler à l’image de l’archimage Modera, près de Dalaran."}},
[97288] = {"Tourment interminable", {"Apportez la tête abominable au maître apothicaire Faranell à Fossoyeuse."}},
[97289] = {"Tourment interminable", {"Apportez la tête du baron au corps d’Othmar, à Fossoyeuse."}},
[97290] = {"Tourment interminable", {"Faites votre rapport au maître apothicaire Faranell, à Fossoyeuse."}},
[97291] = {"Tourment interminable", {"Récupérez un calot toxique auprès de Grisette Fauve dans le quartier des Marchands, de la cloquette auprès de la maîtresse des herboristes et de l’essence d’agonie auprès du marchand de poison du quartier des Voleurs, pour le maître apothicaire Faranell à Fossoyeuse."}},
[97292] = {"Tourment interminable", {"Injectez le sérum sifflant dans le dispositif au-dessus du corps d’Othmar, pour le maître apothicaire Faranell."}},
[97326] = {"Ameublement rocheux", {"Rapportez 8 rochers lisses à Thra derrière le fort Grommash."}},
[97328] = {"Tout ce qui vaut cher", {"Récupérez 8 cargaisons volées dans les ruines de Zul’Kunda, dans la vallée de Strangleronce, et apportez vos trouvailles à quelqu’un, à Baie-du-Butin."}},
[97329] = {"Où est la clé ?", {"Obtenez la clé primitive auprès des Trolls des ruines de Zul’Kunda, dans la vallée de Strangleronce, et apportez-la à Zimmix Krachétincelle."}},
[97331] = {"La grande évasion de Zimmix", {"Conduisez Zimmix Krachétincelle hors des ruines de Zul’Kunda, puis informez le maître des quais Lozouïe de votre sauvetage."}},
[97332] = {"Une confiance deux fois mal placée", {"Apportez le paquet doublement renouvelé au maître des quais Sifflebruit, au port de Poudremèche, sur les rives Claires."}},
[97378] = {"Mirrécaille", {"Apportez l’aile de Mirrécaille à Melor Sabot-de-Pierre, aux Pitons-du-Tonnerre."}},
[97386] = {"L’offensive de Grom’gol", {"Le commandant Aggro’gosh du campement Grom’gol vous demande de tuer des Ogres au tertre des Ogres mosh’Ogg."}},
[97453] = {"Tonte des mauvaises herbes", {"Tuez 6 herbes carnivores au sud de Grom’gol, puis informez la mère de Gemmil."}},
[97485] = {"Traditions des pitons", {"Achetez un paquet d’herbes à Nida l’herboriste, un fagot de brindilles de cèdre à Nata la fournisseuse de composants d’enchantements, des fibres tendineuses à Mahu le fournisseur de matériel de travail du cuir, ainsi que du silex et de l’amadou de cérémonie à Naal le fournisseur de matériel de cuisine.","","Combinez ces composants, puis répandez l’encens depuis la cime des Chasseurs."}},
[97530] = {"Collecte chez les Cognedunes", {"Le chef de la sécurité Bilgewhizzle du port Gentepression en Tanaris veut que vous retrouviez un bracelet particulièrement brillant perdu près de la base des Ogres cognedunes."}},
[97534] = {"Dans le cambouis", {"Quinn vous demande de collecter 7 débris du désert et de les lui rapporter à Gadgetzan."}},
[97536] = {"Déchets gnomes", {"Jhordy Lapforge vous demande de jeter la caisse de déchets radioactifs dans le désert de Tanaris à bonne distance de Gadgetzan et des autres ordures, puis de retourner le voir."}},
[97538] = {"Pigments pour peintures", {"Tah Sabot-d’Hiver des Pitons-du-Tonnerre voudrait obtenir 30 cosses de bourbielle au lac Mirkfallon."}},
[97539] = {"Sutures soyeuses", {"Rapportez 12 soies d’araignée chirurgicales au docteur Gregory Victor au Trépas-d’Orgrim, dans les hautes-terres Arathies."}},
[97540] = {"L’oasis", {"Tooga s’est désaltéré, montrez-lui le chemin du retour vers sa femme, Torta."}},
[97558] = {"Des peaux pour les Réprouvés", {"Apportez à Shelene Rhobart 8 membranes d’ailes de chauve-souris de la pénombre, 6 peaux de sombredogue et 3 peaux de Murloc aileron noir."}},
[97583] = {"GIGOTEMENT.", {"Achetez de la gelée nutritive et apportez-la à votre amie la gelée nerveuse. Si elle paraît fatiguée, essayez de danser avec elle pour attirer son attention."}},
[97617] = {"Contrôles de sécurité", {"Rapportez 8 artéfacts non étudiés, un casque de mineur de la Ligue des explorateurs et un piolet en parfait état à Dorgaron, à la frontière entre le Loch Modan et les terres Ingrates."}},
[97663] = {"Fournitures et études", {"Éliminez des ogres dans la vallée de la Poussière afin de récupérer les fournitures volées de Mus’hale. Utilisez-les ensuite pour réaliser des reproductions des gravures sur pierre des environs, puis retournez auprès de Mus’hale à Kargath."}},
[97821] = {"Miroir du mirage", {"Trouvez quelqu’un dans les terres Ingrates qui s’intéresserait à cette découverte."}},
[97884] = {"Armurerie de Clairsoleil", {"Rendez-vous à Clairsoleil, sur les rives Claires, et récupérez le tome des techniques de forge de la famille Tremayne."}},
[97891] = {"Livraison de potion express", {"Apportez la potion instable au docteur Martin Felben, à l’Apothicarium, avant la fin du temps imparti."}},
[97894] = {"Affaires à Auberdine", {"Prenez des nouvelles de Gorbold Main-d’acier à Auberdine, à Sombrivage.","","Borgus a parlé d’un bateau, au quai le plus au sud du port de Hurlevent, qui peut vous y emmener."}},
