[97977] = {"L’appel de la nature", {"Récupérez 4 totems pins-tordus et apportez-les à Tarindrella."}},
[97979] = {"La déesse pourvoyeuse", {"Lancez Lumière d’Elune et Camouflage dans l’ombre."}},
[97985] = {"Cœurs tonnants", {"Tuez Cœur-d’orage aux Mille pointes et emparez-vous de son cœur."}},
[98013] = {"Forces croissantes", {"Éliminez 12 myrmidons tempécailles, 8 ensorceleuses tempécailles et 6 guerriers tempécailles pour Arbal, au bosquet des Anciens."}},
[98021] = {"En route pour la colline des Sentinelles", {"Allez voir Gryan Roidemantel à la colline des Sentinelles, dans la marche de l’Ouest."}},
[98024] = {"Un voyage à la Croisée", {"Faites votre rapport à Thork à la Croisée, dans les Tarides."}},
[98025] = {"ON RECHERCHE : Jai’vhanel", {"Trouvez Jai’vhanel et terrassez-la, puis récupérez l’une de ses plumes. La chouette noire a été aperçue pour la dernière fois au nord des ruines d’Ameth’Aran, près du pied de la montagne. Signalez la mort de Jai’vhanel à la sentinelle Glynda Nal’Shea, à Auberdine."}},
[98027] = {"Le collier de lune resplendissante", {"Apportez le collier de lune resplendissante à Maliynn à Astranaar."}},
[98028] = {"Baron Marinous", {"Apportez le globe d’eau trouble à Onu, au bosquet des Anciens, à Sombrivage."}},
[98042] = {"Rira bien qui rira le dernier", {"Obtenez un œil sans pareil auprès d’un disciple ou d’un nervi du Crépuscule, au Glaive du Maître à Sombrivage, puis trouvez quelqu’un à Auberdine qui accepte de le prendre."}},
[98046] = {"La couronne de la Terre", {"Rapportez le réceptacle asséché à Lariia, au temple de la Lune, à Darnassus."}},
[98059] = {"Les réserves de Hautebrande", {"Remettez la requête confidentielle de la compagnie qui vous a été confiée à la comptabilité, à l’intérieur de l’hôtel de ville de Hautebrande."}},
[98065] = {"La couronne de la Terre", {"Rapportez les restes de puits de lune à Tyrande Murmevent, au temple de la Lune, à Darnassus."}},
[98067] = {"Regard des Sentinelles", {"Placez des hiboux sentinelles à l’entrée des profondeurs du fort Cénarien, à la banque de Darnassus, à l’auberge de la terrasse des Artisans et aux portes de la ville pour la sentinelle Dalia Lamesoleil au temple de la Lune, à Darnassus."}},
[98069] = {"Les fournitures de Librevent volées", {"Rapportez 8 fournitures de Librevent volées à Jandia, au poste de Librevent."}},
[98070] = {"Interruption des hurlements", {"Tuez 5 harpies hurlantes, 5 Volplumes hurlantes et 5 imploratrices célestes hurlantes."}},
[98071] = {"Échanges brassicoles", {"Apportez les bouteilles de cépage de Ruissautomne à Dun Garok, au sud-est des contreforts de Hautebrande, puis revenez avec un sac de houblon artisanal."}},
[98072] = {"Crocos des cieux", {"Récupérez 8 écailles cramoisies immaculées, puis apportez-les à James Halloran, au port de Menethil."}},
[98093] = {"Un champ à nettoyer", {"Sulhasa des Tarides du sud souhaite que vous éliminiez 7 lézards cuir-tempête et 7 traqueuses jappecroc dans les environs afin qu’elle puisse quitter son arbre en toute sécurité."}},
[98094] = {"Soutien aux éclaireurs", {"La grande exécutrice Darthalia vous charge de remettre des ordres mis à jour au nécrotraqueur Masoj, au sud de Moulin-de-Tarren, à l’extérieur de Dun Garok."}},
[98095] = {"Positions stratégiques", {"Le nécrotraqueur Masoj vous demande de placer les trois flacons d’apothicaire sur les hauteurs des contreforts de Hautebrande, puis de revenir le voir."}},
[98096] = {"Sœurs dans le devoir", {"Trouvez la commandante Chantevrai à la halte de Talrendis, en Azshara, pour obtenir des informations sur ce qu’est devenue Keldara Lamesoleil."}},
[98155] = {"Fourrures pestepoil immaculées", {"Apportez 5 fourrures pestepoil immaculées à Kristy Grant."}},
[98156] = {"Paquet de fourrures immaculées", {"Rapportez le paquet de fourrures immaculées à Kimberly Grant."}},
[98189] = {"Rapporter la statuette", {"Apportez la statuette de Menethil au capitaine Rudepoing, au donjon de Menethil."}},
[98190] = {"Proche de la famille", {"Apportez la statuette de Menethil au généralissime Bolvar Fordragon, au donjon de Hurlevent."}},
[98191] = {"Proche de la famille", {"Apportez la statuette de Menethil au seigneur Grayson Brisombre, à la cathédrale de la Lumière."}},
[98192] = {"Main prudente et lame affûtée", {"Apportez 8 peaux de raptor intactes à Krak, à Mur-de-Fougères."}},
[98197] = {"Butin de guerre", {"Récupérez 6 morceaux de bois de construction de Khaz Modan et 30 unités de fer de Khaz Modan au port de Menethil pour Valstag Gueule-de-fer."}},
[98203] = {"Féticheur Ti’ik", {"Tuez le féticheur fânécorce nommé Ti’ik dans une grotte à l’ouest d’Hiri’watha, puis rapportez sa tête."}},
[98205] = {"Les dragonnets, c’est la plaie !", {"Terrassez 8 jeunes incendiaires et 8 dragonnets incendiaires."}},
[98208] = {"Fleur des cieux", {"Récupérez Nord’el pour Sylessa Murmesoir, au port de Menethil."}},
[98209] = {"Fleur des cieux", {"Apportez Nord’el à Thundris Tissevent à Auberdine, en Sombrivage.","","Sylessa vous a parlé d’un bateau qui peut vous y conduire en partant du port de Menethil."}},
[98215] = {"Écailles de dragon, queues bien grillées", {"Apportez 20 écailles de dragon sombre tombées à Drazzit Suintevalve."}},
[98216] = {"Comprendre notre présent", {"Utilisez la pierre de Goaz près du gardien de Goaz, puis rapportez sa pierre-clé titanesque au prospecteur Whelgar."}},
[98219] = {"Le lieutenant déshonoré", {"Allez parler au lieutenant Farren Orinelle à Austrivage, dans les contreforts de Hautebrande."}},
[98221] = {"Tiré des cendres", {"Le capitaine Rudepoing du donjon de Menethil vous demande de détruire 4 plans d’attaque dans le campement de Hargnecroc."}},
[98223] = {"Vieilles habitudes", {"Rapportez le grimoire en lambeaux au capitaine Rudepoing, au port de Menethil."}},
[98230] = {"Cette terre était la leur", {"Trouvez Howin Genteplume le long de la route à l’est du port de Menethil."}},
[98231] = {"Principe actif", {"Apportez 10 queues de wyrm à Gizzix Glougloutache."}},
[98233] = {"L’épée dans la vase", {"Récupérez l’épée d’entraînement de Jameson et rapportez-la au garde Jameson."}},
[98240] = {"Livraison de caisse cramoisie", {"Apportez la caisse cramoisie à Howin Genteplume, près de la route à l’est du port de Menethil."}},
[98245] = {"Travail d’aiguille tranchegueule", {"Obtenez 10 incisives de tranchegueule pour Howin Genteplume."}},
[98246] = {"Période de disette", {"Obtenez 12 œufs de tranchegueule en parfait état pour Howin Genteplume."}},
[98247] = {"Étiquette d’envoi", {"Apportez l’étiquette d’envoi au personnel du poste de l’Administration commerciale d’Azeroth dans les Carmines."}},
[98248] = {"Étiquette d’envoi", {"Apportez l’étiquette d’envoi au personnel du poste des Transports logistiques Durotar près de la Croisée dans les Tarides."}},
[98251] = {"Point de non-retour", {"Tuez 6 cerfs à corne noireet 6 ours d’Orneval, puis retournez auprès de Va’xug Cendrerage, au nord-ouest du lac Tombeciel."}},
[98252] = {"La voie du Vide", {"Guidez l’Œil de Kilrogg de Va’xug jusqu’à la route principale d’Orneval."}},
[98282] = {"Dangers alchimiques", {"Procurez-vous une glande de traqueur intacte au rocher de Thelgen, et apportez-la à Caitlin Grassman, au port de Menethil."}},
[98283] = {"Carnage", {"Apportez la tête de Carnage à Rethiel le Gardien vert, dans la Ceinture verte."}},
[98284] = {"Introduction au camping : l’enchantement", {"Parlez à Nasalanna Chantelevent, à Shen’dar, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main."}},
[98285] = {"Introduction au camping : l’ingénierie", {"Parlez à l’étrange ermite, dans la forêt de Trombenoire, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main."}},
[98286] = {"Introduction au camping : l’enchantement", {"Parlez à Nasalanna Chantelevent, à Shen’dar, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main."}},
[98291] = {"Mort aux Gueules-de-Dragon", {"Tuez 8 récupérateurs gueules-de-dragon, 5 lieurs d’âme gueules-de-dragon et 3 infitrateurs gueules-de-dragon dans la retraite des Gueules-de-dragon afin d’aider Howin Genteplume."}},
[98293] = {"Désarmement forcé", {"Récupérez 30 armes gueules-de-dragon dans la retraite des Gueules-de-dragon, puis apportez-les au capitaine Rudepoing, au donjon de Menethil."}},
[98297] = {"Rompre le cycle", {"Tuez le draconide maîtrisé aux portes des Gueules-de-dragon, comme vous l’a demandé Howin Genteplume."}},
[98298] = {"La folie d’Arugal", {"Rapportez 6 morceaux worgens à Dalar Tisselaube au Sépulcre."}},
[98299] = {"Endiguer la propagation", {"Tuez 5 réfugiés malades et 5 réfugiés hagards pour Dalar Tisselaube au Sépulcre."}},
[98300] = {"Prévenir Forgefer", {"Apportez la missive de Howin au roi Magni Barbe-de-Bronze, à Forgefer."}},
[98310] = {"Entrevoir notre avenir", {"Utilisez la pierre de Goaz près d’Adoss, Modr, Golm et Neru, puis rapportez leurs cœurs au prospecteur Whelgar."}},
[98313] = {"Études approfondies", {"Remettez le paquet de reliques de Whelgar à l’historien Karnik, à Forgefer."}},
[98319] = {"Sécuriser la montagne", {"Trouvez le montagnard Cornélius dans l’antre Gris pour la montagnarde Gretchen."}},
[98321] = {"Cargaison de Flammesilex", {"Récupérez 8 cargaisons de Flammesilex à l’antre Gris pour Tongus Flammesilex, à Kharanos."}},
[98322] = {"Sécuriser la montagne", {"Allez voir la montagnarde Gretchen à l’ouest de Kharanos."}},
[98323] = {"Sécuriser la montagne", {"Apportez le rapport de la montagnarde Gretchen à Senir Blanchebarbe, à Kharanos."}},
[98326] = {"Hurlegivre", {"Éliminez Hurlegivre et récupérez le sac de poissons de Gretta Ganter, à Brassetout."}},
