[98341] = {"L’esprit du Grand félin du vent", {"Partez à la recherche de l’avatar de Saeyleenan dans la partie sud de Reflet-de-Lune et découvrez ce qu’il peut vous apprendre sur la nature du félin du vent."}},
[98342] = {"L’esprit du Grand félin", {"Récupérez la relique du croc, la relique de la griffe et la relique de l’ombre furtive dans le refuge des saisons de Malfurion, puis rapportez-les à l’esprit du Grand félin."}},
